function renderPortalStreetMap(containerId){const container=document.getElementById(containerId);if(!container||!window.L)return;if(portalStreetMap){portalStreetMap.remove();portalStreetMap=null}portalStreetMap=L.map(container,{zoomControl:false,scrollWheelZoom:true,attributionControl:true,minZoom:6,maxZoom:18}).setView([44.2,20.8],7);L.control.zoom({position:'bottomright'}).addTo(portalStreetMap);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(portalStreetMap);const bounds=[];portalMapLocations.forEach(location=>{const marker=L.circleMarker(location.coords,{radius:10,color:'#fff',weight:3,fillColor:location.tone,fillOpacity:1}).addTo(portalStreetMap);marker.bindPopup(`<div class="portal-map-popup"><strong>${location.name}</strong><span>${location.city} · ${location.type}</span><small>${location.detail}</small><button type="button" data-portal-map-screen="${location.screen}">Otvori radni prostor</button></div>`);marker.on('click',()=>showToast(`${location.name} · ${location.city}`));bounds.push(location.coords)});portalStreetMap.fitBounds(bounds,{padding:[42,42]});setTimeout(()=>portalStreetMap?.invalidateSize(),0)}
function centerPortalStreetMap(){if(!portalStreetMap)return;portalStreetMap.fitBounds(portalMapLocations.map(location=>location.coords),{padding:[42,42]});showToast('Prikazane su demonstracione akcije širom Srbije.')}
async function searchPortalMap(){const input=$('#portal-map-search');const query=input?.value.trim();if(!query){showToast('Unesite grad ili mesto u Srbiji.');input?.focus();return}const localMatch=portalMapLocations.find(location=>`${location.name} ${location.city}`.toLocaleLowerCase('sr').includes(query.toLocaleLowerCase('sr')));if(localMatch){portalStreetMap?.setView(localMatch.coords,13,{animate:true});showToast(`${localMatch.city} · prikazane su povezane akcije.`);return}try{const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=rs&accept-language=sr&q=${encodeURIComponent(`${query}, Srbija`)}`);const results=await response.json();const place=results[0];if(!place)throw new Error('Nema rezultata');portalStreetMap?.setView([Number(place.lat),Number(place.lon)],13,{animate:true});showToast(`Karta je prebačena na: ${place.display_name.split(',').slice(0,2).join(',')}.`)}catch(error){showToast('Mesto nije pronađeno. Pokušajte naziv grada ili opštine u Srbiji.')}}

function renderMobileList(){
  $('#mobile-screen-list').innerHTML=mobileCatalog.map(group=>`<section class="screen-group"><h3>${group.title}</h3>${group.items.map(([id,label])=>`<button data-mobile-screen="${id}">${label}</button>`).join('')}</section>`).join('');
}

function renderChecklist(){
  const items=screenDecisions[state.mobileScreen]||screenDecisions.home;
  $('#decision-checklist').innerHTML=items.map((item,index)=>`<div class="check-item"><span>${index+1}</span><div><strong>${item[0]}</strong><small>${item[1]}</small></div></div>`).join('');
}

function renderMobile(screen=state.mobileScreen){
  state.mobileScreen=screen;
  const labels=Object.fromEntries(mobileCatalog.flatMap(group=>group.items));
  $('#mobile-flow-label').textContent=labels[screen]||screen;
  $$('#mobile-screen-list [data-mobile-screen]').forEach(button=>button.classList.toggle('active',button.dataset.mobileScreen===screen));
  const root={actions:'actions','action-detail':'actions',booking:'actions','booking-success':'actions',appointments:'actions',notifications:'notifications',profile:'profile',card:'profile',history:'profile','donation-detail':'profile',corrections:'profile',achievements:'profile',privacy:'profile',pause:'profile',questionnaire:'profile'}[screen]||'home';
  const onboarding=['welcome','registration','verification','link-record'].includes(screen);
  $('#mobile-nav').classList.toggle('hidden',onboarding);
  $$('#mobile-nav [data-mobile-screen]').forEach(button=>button.classList.toggle('active',button.dataset.mobileScreen===root));
  mobileScreen.innerHTML=mobileTemplates[screen]?.()||mobileTemplates.home();
  if(screen==='actions'&&state.actionsView==='map')requestAnimationFrame(renderStreetMap);
  mobileScreen.scrollTop=0;
  renderChecklist();
  history.replaceState(null,'',`#mobile/${screen}`);
}

