  booking:()=>`${mobileHeader('Izbor termina','action-detail')}<div class="detail-hero"><span class="small-label">DOM OMLADINE</span><h3>Subota, 12. oktobar</h3><p class="helper">Izaberite slobodno vreme dolaska.</p></div><div class="section-heading"><h3>Prepodne</h3></div><div class="time-grid">${['10:00','10:30','11:00','11:30','12:00','12:30'].map((time,index)=>`<button class="time-slot ${time===state.selectedTime?'selected':''}" data-time="${time}" ${index===2?'disabled':''}>${time}</button>`).join('')}</div><div class="choice-card selected"><input type="checkbox" checked><div><strong>Podseti me</strong><small>Dan ranije i dva sata pre termina.</small></div></div><div class="warning-box" style="margin-top:12px">Pre potvrde sistem ponovo proverava raspoloživu evidenciju. Ovo nije medicinsko odobrenje.</div><button class="primary-button full" style="margin-top:14px" data-action="confirm-booking">Potvrdi ${state.selectedTime}</button>`,
  'booking-success':()=>`<section class="success-state"><div class="success-mark">✓</div><h2>Termin je potvrđen</h2><p>Subota, 12. oktobar u ${state.selectedTime}<br>Dom omladine, Beograd</p><div class="digital-card" style="text-align:left;margin-top:20px"><span class="small-label" style="color:#f4d9de">BROJ REZERVACIJE</span><h3 style="font-size:1.6rem;letter-spacing:.12em">DK-284913</h3><p>Prikažite kod na prijemu ako vas zaposleni zatraži.</p></div><div class="onboarding-actions"><button class="primary-button full" data-mobile-screen="appointments">Moji termini</button><button class="ghost-button" data-mobile-screen="home">Nazad na početnu</button></div></section>`,
