  'donation-detail':()=>`${mobileHeader('Detalj davanja','history')}<article class="detail-hero"><span class="pill success">Potvrđeno</span><h3>14. jun 2024.</h3><p class="helper">Puna krv</p></article><div class="detail-list"><div class="detail-row"><span>⌖</span><div><strong>Institut za transfuziju</strong><small>Beograd</small></div></div><div class="detail-row"><span>✓</span><div><strong>Evidentirano 14. juna u 13:48</strong><small>Potvrdio ovlašćeni zaposleni</small></div></div><div class="detail-row"><span>▤</span><div><strong>Potvrda o davanju</strong><small>Zvanični dokument ustanove</small></div></div></div><button class="primary-button full" data-action="download-certificate">Preuzmi potvrdu</button><button class="ghost-button" style="width:100%;margin-top:8px" data-mobile-screen="corrections">Prijavi grešku</button>`,
