  achievements:()=>`${mobileHeader('Kapljice i jubileji','profile')}<section class="achievement-hero"><span class="achievement-count">5</span><div><span class="small-label">POTVRĐENIH DAVANJA</span><h3>Svako davanje ostavlja trag dobrote.</h3><p>Jubileji beleže kontinuitet — bez rangiranja i pritiska.</p></div></section><section class="giving-path" aria-label="Put davanja i jubileja"><div class="path-line"></div><article class="path-item earned"><span class="path-dot">♥</span><div><small>14. jun 2024.</small><strong>5. davanje</strong><p>Jubilej kontinuiteta</p></div></article><article class="path-item"><span class="path-dot">●</span><div><small>2. novembar 2023.</small><strong>4. davanje</strong><p>Potvrđeno u evidenciji</p></div></article><article class="path-item"><span class="path-dot">●</span><div><small>18. mart 2023.</small><strong>3. davanje</strong><p>Potvrđeno u evidenciji</p></div></article><article class="path-item future"><span class="path-dot">10</span><div><small>Sledeći jubilej</small><strong>10 davanja</strong><p>Još 5 potvrđenih davanja</p></div></article></section><div class="section-heading"><h3>Zahvalnice</h3><button data-action="show-thanks">Prikaži sve</button></div><div class="gratitude-grid"><button class="gratitude-card" data-action="show-thanks"><span>♥</span><strong>Hvala što dajete</strong><small>Za 5 potvrđenih davanja</small></button><button class="gratitude-card coral" data-action="show-thanks"><span>✦</span><strong>Kap kontinuiteta</strong><small>Vaša najnovija zahvalnica</small></button></div><button class="secondary-button" data-action="share-achievement">Podeli zahvalnicu</button>`,
