  education:()=>`${mobileHeader('Vesti i edukacija','home',`<button class="icon-button" aria-label="Pretraga">${icon('search')}</button>`)}<div class="chips education-chips"><button class="chip active">Sve</button><button class="chip">Prvo davanje</button><button class="chip">Priprema</button><button class="chip">Afereza</button></div><article class="article-card"><span class="article-tag">Vodič</span><h3>Prvi put dajete krv?</h3><p>Šta poneti, koliko traje i šta se dešava u svakoj fazi.</p></article><article class="article-card"><span class="article-tag">Priprema</span><h3>Dan pre davanja</h3><p>Odobrene preporuke o odmoru, obroku i unosu tečnosti.</p></article><article class="article-card"><span class="article-tag">Vest Zavoda</span><h3>Izmena radnog vremena</h3><p>Ažurirano danas u 08:15 · zvanična informacija.</p></article><button class="secondary-button" data-mobile-screen="faq">Česta pitanja</button>`,
