function intakeCounts(){return {scheduled:adminIntakeRows.filter(row=>row[4]==='Zakazan').length,checkedIn:adminIntakeRows.filter(row=>row[4]==='Prijavljen').length,medical:adminIntakeRows.filter(row=>row[4]==='Kod tima').length,noShow:adminIntakeRows.filter(row=>row[4]==='Nije došao').length}}
function filteredIntakeRows(){const search=state.operationsQuery.trim().toLocaleLowerCase('sr');return adminIntakeRows.filter(row=>(state.operationsStatus==='all'||row[4]===state.operationsStatus)&&(!search||`${row[0]} ${row[2]} ${row[3]}`.toLocaleLowerCase('sr').includes(search)))}
function intakeRow([name,initials,code,time,status]){return `<tr tabindex="0" data-action="open-intake-record" data-reservation="${code}"><td><div class="person-cell"><span class="tiny-avatar">${initials}</span><div><strong>${name}</strong><br><small>${code}</small></div></div></td><td>${time}</td><td>${pill(status,statusTone(status))}</td><td><button class="table-button" data-action="open-intake-record" data-reservation="${code}">Detalj</button></td></tr>`}
function portalEventDay(event){return (event.date.match(/^(\d{1,2})/)||[])[1]||''}
function filteredEvents(){const search=state.eventQuery.trim().toLocaleLowerCase('sr');return portalEvents.filter(event=>(!state.selectedPortalDay||portalEventDay(event)===state.selectedPortalDay)&&(state.eventMunicipality==='all'||event.place===state.eventMunicipality)&&(state.eventStatus==='all'||event.status===state.eventStatus)&&(!search||`${event.name} ${event.place}`.toLocaleLowerCase('sr').includes(search)))}
function portalEventRow(event){return `<tr tabindex="0" data-action="edit-event" data-event="${event.id}"><td><strong>${event.name}</strong><br><small>${event.place}</small></td><td>${event.date}</td><td>${event.access}</td><td><div class="occupancy"><span>${event.capacity}</span><span class="bar"><span style="width:${event.percent}%"></span></span></div></td><td>${pill(event.status,event.tone)}</td><td><button class="table-button" data-action="edit-event" data-event="${event.id}">Otvori</button></td></tr>`}

const portalTemplates={
  dashboard:()=>{const counts=intakeCounts();return `${portalHeader('OPERATIVNI DEMO · DOM OMLADINE','Operativni pregled','<button class="primary-button compact" data-portal-screen="events">+ Nova akcija</button>')}<div class="metric-grid">${metric('Zakazano',counts.scheduled,'čekaju prijem')}${metric('Prijavljeni',counts.checkedIn,'u redu za medicinski tim')}${metric('Kod medicinskog tima',counts.medical,'logistički signal predat')}${metric('Nisu došli',counts.noShow,'evidentira prijem')}</div><div class="portal-grid">${panel('Današnja akcija',`<div class="action-row"><span class="status live"></span><div><strong>Dom omladine</strong><small>10:00–14:00 · Prijem 1 · 13 demonstracionih termina</small></div><button class="table-button" data-portal-screen="operations">Otvori tok</button></div><div class="info-box" style="margin-top:12px">Portal prati zbirni operativni status. Prijem radi u zasebnoj aplikaciji, a medicinski podaci nisu dostupni ovde.</div>`,'<p>Akcija, kapacitet i statusi bez zdravstvenih detalja</p>')}${panel('Sledeće radnje',`<div class="task-row"><span class="task-icon">↗</span><div><strong>Prati prijem i nedolaske</strong><small>Otvorite operativni tok sa tačnim statusima.</small></div><button class="table-button" data-portal-screen="operations">Otvori</button></div><div class="task-row"><span class="task-icon neutral">!</span><div><strong>Ispravke evidencije</strong><small>Zahtevi davalaca čekaju proveru.</small></div><button class="table-button" data-portal-screen="donors">Pregled</button></div><div class="task-row"><span class="task-icon neutral">3</span><div><strong>Tekstovi za stručnu proveru</strong><small>Sadržaj nije javno objavljen.</small></div><button class="table-button" data-portal-screen="content">Pregled</button></div>`,'<p>Svaka radnja ostaje u okviru odgovarajuće uloge</p>')}</div>`},
  events:()=>`${portalHeader('AKCIJE I TERMINI','Kalendar akcija','<button class="ghost-button" data-action="import-schedule">Uvezi raspored</button><button class="primary-button compact" data-action="create-event">+ Nova akcija</button>')}<div class="calendar-strip">${[['PON','14'],['UTO','15'],['SRE','16'],['ČET','17'],['PET','18'],['SUB','19'],['NED','20']].map(([day,date])=>`<button class="day-cell ${date===state.selectedPortalDay?'active':''}" data-action="select-portal-day" data-day="${date}"><span>${day}</span><strong>${date}</strong></button>`).join('')}</div>${panel('Akcije ove nedelje',`<div class="toolbar"><input class="search-input" data-portal-filter="events-query" value="${state.eventQuery}" placeholder="Pretraži naziv, mesto ili organizatora"><select class="select-control" data-portal-filter="events-municipality"><option value="all">Sve opštine</option><option value="Beograd" ${state.eventMunicipality==='Beograd'?'selected':''}>Beograd</option><option value="Novi Sad" ${state.eventMunicipality==='Novi Sad'?'selected':''}>Novi Sad</option><option value="Zemun" ${state.eventMunicipality==='Zemun'?'selected':''}>Zemun</option></select><select class="select-control" data-portal-filter="events-status"><option value="all">Svi statusi</option><option value="U toku" ${state.eventStatus==='U toku'?'selected':''}>U toku</option><option value="Objavljeno" ${state.eventStatus==='Objavljeno'?'selected':''}>Objavljeno</option><option value="Nacrt" ${state.eventStatus==='Nacrt'?'selected':''}>Nacrt</option></select></div><table class="data-table"><thead><tr><th>Akcija</th><th>Datum i vreme</th><th>Pristup</th><th>Popunjenost</th><th>Status</th><th></th></tr></thead><tbody>${filteredEvents().map(portalEventRow).join('')||'<tr><td colspan="6" class="empty-table">Nema akcija za izabrane filtere.</td></tr>'}</tbody></table>`,'<p>Pretraga i filteri rade nad demonstracionim skupom podataka</p>','table-panel')}`,
  checkin:()=>`${portalHeader('PRIJEM DAVALACA','Odvojeni radni prostor','<button class="primary-button compact" data-portal-screen="operations">Otvori tok prijema</button>')}<div class="portal-grid equal">${panel('Šta radi prijem',`<div class="task-row"><span class="task-icon">1</span><div><strong>Pronalazi tačnu rezervaciju</strong><small>QR kod ili broj rezervacije, pa provera identiteta uživo.</small></div></div><div class="task-row"><span class="task-icon">2</span><div><strong>Evidentira dolazak jednom</strong><small>Dupla prijava ne pravi novu posetu.</small></div></div><div class="task-row"><span class="task-icon">3</span><div><strong>Predaje samo logistički signal</strong><small>Medicinski tim otvara zaseban odobreni tok.</small></div></div>`,'<p>Prijem ne vidi zdravstvenu istoriju, krvnu grupu ni procenu podobnosti</p>')}${panel('Šta radi portal',`<div class="task-row"><span class="task-icon neutral">✓</span><div><strong>Prati zbirni operativni tok</strong><small>Zakazano, prijavljeno, kod medicinskog tima i nedolasci.</small></div></div><div class="task-row"><span class="task-icon neutral">↗</span><div><strong>Ne otvara karton davaoca</strong><small>Detalj rezervacije ostaje u ulozi prijema.</small></div></div><button class="primary-button full" style="margin-top:14px" data-portal-screen="operations">Otvori tok prijema</button>`,'<p>Administrator i koordinator vide samo minimum potreban za logistiku</p>')}</div>`,
  operations:()=>{const counts=intakeCounts(), rows=filteredIntakeRows();return `${portalHeader('DOM OMLADINE · PRIJEM 1','Tok prijema','<button class="ghost-button" data-action="refresh-operations">Osveži tok</button><button class="primary-button compact" data-portal-screen="checkin">Model uloga</button>')}<div class="metric-grid">${metric('Zakazano',counts.scheduled,'čeka prijem')}${metric('Prijavljeni',counts.checkedIn,'u redu za tim')}${metric('Kod medicinskog tima',counts.medical,'predati logistički')}${metric('Nisu došli',counts.noShow,'može označiti prijem')}</div>${panel('Današnji termini',`<div class="toolbar"><input class="search-input" data-portal-filter="operations-query" value="${state.operationsQuery}" placeholder="Pretraži ime ili broj rezervacije"><select class="select-control" data-portal-filter="operations-status"><option value="all">Svi operativni statusi</option><option value="Zakazan" ${state.operationsStatus==='Zakazan'?'selected':''}>Zakazano</option><option value="Prijavljen" ${state.operationsStatus==='Prijavljen'?'selected':''}>Prijavljeni</option><option value="Kod tima" ${state.operationsStatus==='Kod tima'?'selected':''}>Kod medicinskog tima</option><option value="Nije došao" ${state.operationsStatus==='Nije došao'?'selected':''}>Nisu došli</option></select><span class="result-count">${rows.length} od ${adminIntakeRows.length} termina</span></div><table class="data-table"><thead><tr><th>Davalac</th><th>Termin</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(intakeRow).join('')||'<tr><td colspan="4" class="empty-table">Nema termina koji odgovaraju izabranom filteru.</td></tr>'}</tbody></table><div class="info-box" style="margin-top:14px">Demonstracioni operativni prikaz: portal prati samo termin i status. Osnovni identitet je radni podatak sintetičke demonstracije; zdravstveni podaci nisu deo portala.</div>`,'<p>Pretraga, filter i detalj rade nad istim demonstracionim skupom</p>','table-panel')}`},
  campaigns:()=>`${portalHeader('CILJANI POZIVI','Kampanje i talasi','<button class="primary-button compact" data-portal-screen="campaign-builder">+ Nova kampanja</button>')}<div class="metric-grid">${metric('Aktivne','3','dve teritorijalne')}${metric('Čekaju odobrenje','1','publika spremna')}${metric('Rezervacije iz kampanja','68','ovog meseca',true)}${metric('Ograničenje učestalosti','7 dana','između sličnih poziva')}</div>${panel('Aktivne kampanje',`<table class="data-table"><thead><tr><th>Kampanja</th><th>Cilj</th><th>Talasi</th><th>Rezervacije</th><th>Status</th><th></th></tr></thead><tbody><tr><td><strong>Potreba za 0−</strong><br><small>Beograd · puna krv</small></td><td>20 dolazaka</td><td>2 od 3</td><td>16</td><td>${pill('Aktivna','success')}</td><td><button class="table-button" data-portal-screen="campaign-detail">Prati</button></td></tr><tr><td><strong>Akcija Novi Sad</strong><br><small>Južnobački okrug</small></td><td>35 dolazaka</td><td>1 od 2</td><td>22</td><td>${pill('Aktivna','success')}</td><td><button class="table-button">Prati</button></td></tr><tr><td><strong>Kompanija Dunav</strong><br><small>Samo zaposleni</small></td><td>25 dolazaka</td><td>nije pokrenuto</td><td>0</td><td>${pill('Čeka odobrenje','warning')}</td><td><button class="table-button" data-portal-screen="campaign-builder">Pregled</button></td></tr></tbody></table>`,'<p>Poslato, otvoreno, zakazano i realizovano ostaju odvojeni rezultati</p>','table-panel')}`,
  'campaign-builder':()=>`${portalHeader('NOVA KAMPANJA','Podešavanje publike','<button class="ghost-button" data-portal-screen="campaigns">Sačuvaj nacrt</button>')}<div class="builder-steps"><span class="active">1 Kriterijumi</span><span>2 Publika</span><span>3 Poruka</span><span>4 Odobrenje</span></div><div class="portal-grid">${panel('Kriterijumi kampanje',`<div class="form-grid"><div class="field"><label>Naziv</label><input value="Potreba za 0− · Beograd"></div><div class="field"><label>Vrsta davanja</label><select><option>Puna krv</option><option>Komponente</option></select></div><div class="field"><label>Krvna grupa</label><select><option>0−</option><option>0+</option><option>Sve grupe</option></select></div><div class="field"><label>Teritorija</label><select><option>Beograd</option><option>Novi Sad</option></select></div><div class="field"><label>Cilj potvrđenih dolazaka</label><input type="number" value="20"></div><div class="field"><label>Veličina prvog talasa</label><input type="number" value="50"></div></div><button class="primary-button compact" style="margin-top:15px" data-action="preview-audience">Ponovo izračunaj publiku</button>`,'<p>Medicinske kriterijume podešava samo ovlašćena uloga</p>')}${panel('Pregled publike',`<div class="audience-preview"><span class="small-label">ODGOVARA KRITERIJUMIMA</span><div class="audience-total">50 davalaca</div><p class="muted">Izračunato pre 2 minuta iz poslednje dostupne evidencije.</p><ul class="exclusion-list"><li><span>Vremenski razmak nije istekao</span><strong>18</strong></li><li><span>Aktivna pauza korisnika</span><strong>7</strong></li><li><span>Već pozvani sličnom kampanjom</span><strong>12</strong></li><li><span>Podatak nije dovoljno ažuran</span><strong>5</strong></li></ul></div><div class="warning-box" style="margin-top:12px">Publika se ponovo proverava neposredno pre svakog talasa.</div><button class="primary-button full" style="margin-top:12px" data-portal-screen="campaign-detail">Nastavi na pregled talasa</button>`,'<p>Razlozi isključenja bez otkrivanja zdravstvenih detalja</p>')}</div>`,
  'campaign-detail':()=>`${portalHeader('KAMPANJA · 0−','Praćenje talasa','<button class="danger-button" data-action="pause-campaign">Pauziraj kampanju</button>')}<div class="metric-grid">${metric('Cilj','20','potvrđenih dolazaka')}${metric('Zakazano','16','80% cilja')}${metric('Realizovano','9','potvrđeno')}${metric('Kapacitet','6','slobodnih termina')}</div>${panel('Talasi pozivanja',`<div class="wave-row"><span class="wave-label">Talas 1</span><span class="wave-progress"><span style="width:100%"></span></span><strong>50 poslato</strong><span>${pill('Završen','success')}</span></div><div class="wave-row"><span class="wave-label">Talas 2</span><span class="wave-progress"><span style="width:68%"></span></span><strong>34 poslato</strong><span>${pill('Aktivan','info')}</span></div><div class="wave-row"><span class="wave-label">Talas 3</span><span class="wave-progress"><span style="width:0%"></span></span><strong>0 poslato</strong><span>${pill('Čeka','neutral')}</span></div><div class="info-box" style="margin-top:14px">Sistem predlaže da se sačeka još 2 sata. Ovlašćeni zaposleni odlučuje da li se pokreće naredni talas.</div><div class="button-row portal-button-row"><button class="primary-button compact" data-action="launch-wave">Pokreni naredni talas</button><button class="ghost-button">Izmeni kriterijume</button></div>`,'<p>Automatsko zaustavljanje pri popunjenom cilju ili kapacitetu</p>')}`,
  donors:()=>`${portalHeader('DAVAOCI I PROVERE','Pretraga i zahtevi','<button class="ghost-button">Izvezi zbirni pregled</button>')}<div class="toolbar"><input class="search-input" placeholder="Ime, broj davaoca ili kontakt"><select class="select-control"><option>Svi zahtevi</option><option>Ispravke evidencije</option><option>Povezivanje naloga</option></select><button class="primary-button compact" data-action="search-donor">Pretraži</button></div><div class="portal-grid">${panel('Zahtevi koji čekaju',`<div class="task-row"><span class="task-icon">!</span><div><strong>Nedostaje davanje · Milica Petrović</strong><small>Prijavljeno 19. septembra · dokaz priložen</small></div><button class="table-button" data-action="review-correction">Otvori</button></div><div class="task-row"><span class="task-icon neutral">ID</span><div><strong>Povezivanje naloga · Nikola Jovanović</strong><small>Moguće podudaranje sa dva zapisa</small></div><button class="table-button">Otvori</button></div><div class="task-row"><span class="task-icon neutral">?</span><div><strong>Netačan datum · Ana Simić</strong><small>Prijavljeno juče</small></div><button class="table-button">Otvori</button></div>`,'<p>Pristup je ograničen ulogom zaposlenog</p>')}${panel('Pravila pristupa',`<div class="role-card"><h3>Koordinator akcija</h3><p>Vidi termine i logističke podatke, ali ne vidi zdravstvene odgovore.</p></div><div class="role-card" style="margin-top:9px"><h3>Medicinska služba</h3><p>Vidi zdravstveni upitnik i beleži ishod prema odobrenom postupku.</p></div><div class="role-card" style="margin-top:9px"><h3>PR i sadržaj</h3><p>Vidi samo zbirne rezultate i javne sadržaje.</p></div>`,'<p>Najmanji potreban obim podataka</p>')}</div>`,
  inventory:()=>`${portalHeader('ZALIHE KRVI','Stanje i javni prikaz','<button class="primary-button compact" data-action="save-inventory">Sačuvaj ažuriranje</button>')}<div class="info-box" style="margin-bottom:15px">Prikaz se odnosi na Institut za transfuziju i punu krv. Poslednje potvrđeno ažuriranje: danas u 08:30.</div><div class="blood-grid">${[['A+','Stabilno','18 dana',''],['A−','Niska zaliha','4 dana','low'],['B+','Stabilno','12 dana',''],['B−','Potrebno','3 dana','low'],['AB+','Stabilno','9 dana',''],['AB−','Kritično','1 dan','critical'],['0+','Niska zaliha','5 dana','low'],['0−','Kritično','1 dan','critical']].map(([group,status,level,cls])=>`<article class="blood-card ${cls}"><h3>${group}</h3><strong>${level}</strong><p>${status}</p><select class="select-control" style="width:100%"><option>${status}</option><option>Stabilno</option><option>Niska zaliha</option><option>Kritično</option></select></article>`).join('')}</div><div class="warning-box" style="margin-top:15px">Promena zaliha ne pokreće automatski masovne poruke. Kampanju otvara i odobrava odgovorna osoba.</div>`,
  content:()=>`${portalHeader('SADRŽAJ I PODRŠKA','Uređivanje i odobravanje','<button class="ghost-button">Sačuvaj nacrt</button><button class="primary-button compact" data-action="publish-content">Pošalji na odobrenje</button>')}<div class="editor-layout"><section class="editor-area"><span class="eyebrow">VODIČ ZA PRVO DAVANJE</span><h2>Kako da se pripremite za prvo davanje krvi</h2><p>Pre dolaska pojedite lagan obrok i pijte dovoljno tečnosti. Ponesite dokument sa fotografijom i odvojite vreme za prijem, razgovor i pregled.</p><p>Digitalna informacija ne zamenjuje razgovor sa zdravstvenim radnikom. Konačnu odluku o davanju donosi lekar prilikom svake posete.</p><div class="field"><label>Izvor i datum stručne provere</label><input value="Stručna služba Zavoda · provereno 18. septembra 2026."></div></section><aside><div class="revision-card"><strong>Status</strong><p>${pill('Stručna provera','warning')}</p></div><div class="revision-card"><strong>Verzija 4</strong><p class="muted">Jelena je izmenila uvod.</p><small>Danas u 10:14</small></div><div class="revision-card"><strong>Verzija 3</strong><p class="muted">Dr Marković je odobrio medicinski deo.</p><small>Juče u 16:48</small></div></aside></div>`,
  reports:()=>`${portalHeader('IZVEŠTAJI','Rezultati bez pogrešnih zaključaka','<button class="primary-button compact" data-action="export-report">Preuzmi izveštaj</button>')}<div class="metric-grid">${metric('Poslato','1.240','poruka')}${metric('Otvoreno','746','60% dostavljenih')}${metric('Zakazano','214','17% poslatih')}${metric('Realizovano','168','potvrđenih davanja')}</div><div class="portal-grid">${panel('Rezultat po mesecima',`<div class="chart">${[['APR',52],['MAJ',68],['JUN',83],['JUL',61],['AVG',74],['SEP',92]].map(([label,value])=>`<div class="chart-bar" style="height:${value}%"><strong>${value}</strong><span>${label}</span></div>`).join('')}</div>`,'<p>Potvrđena davanja povezana sa terminima i kampanjama</p>')}${panel('Napomena za tumačenje',`<div class="info-box">Poslata poruka, iskazana namera, rezervacija, dolazak i potvrđeno davanje nisu isti rezultat.</div><div class="task-row"><span class="task-icon neutral">1</span><div><strong>Novi davaoci</strong><small>34 potvrđena prva davanja</small></div></div><div class="task-row"><span class="task-icon neutral">2</span><div><strong>Ponovni dolasci</strong><small>61% u odabranom periodu</small></div></div>`,'<p>Metrike ostaju jasno razdvojene</p>')}</div>`,
  staff:()=>`${portalHeader('SISTEMSKA ADMINISTRACIJA','Osoblje, pozicije i odgovornosti','<button class="ghost-button" data-portal-screen="access">Matrica dozvola</button><button class="primary-button compact" data-action="create-staff-invite">+ Pozovi osoblje</button>')}<div class="super-admin-callout"><span class="super-admin-mark">SA</span><div><strong>Super admin određuje pristup</strong><p>Samo Super admin kreira poziciju, određuje odgovornost, dodeljuje akciju i aktivira ili opoziva nalog. Svaka promena ostavlja audit trag.</p></div><button class="table-button" data-action="open-super-admin">Pogledaj ovlašćenje</button></div>${panel('Osoblje Zavoda',`<div class="staff-directory">${staffDirectory.map(member=>`<article class="staff-card" data-action="open-staff-member" data-staff="${member.id}"><span class="staff-avatar">${member.initials}</span><div class="staff-main"><strong>${member.name}</strong><small>${member.position}</small><p>${member.responsibility}</p><span class="staff-action">${member.actions}</span></div><div class="staff-state">${pill(member.status,member.tone)}<button class="table-button" data-action="open-staff-member" data-staff="${member.id}">Upravljaj</button></div></article>`).join('')}</div>`,'<p>Pozicija i dodeljena odgovornost su odvojene od zdravstvenih podataka</p>','full-span')}`,
  access:()=>`${portalHeader('UPRAVLJANJE PRISTUPOM','Matrica uloga i odgovornosti','<button class="ghost-button" data-portal-screen="staff">Osoblje i pozicije</button><button class="primary-button compact" data-action="create-staff-invite">+ Nova pozivnica</button>')}<div class="role-grid role-grid-wide">${roleCatalog.map(item=>`<article class="role-card ${item.role==='super_admin'?'super-admin-card':''}"><span class="small-label">${item.role}</span><h3>${item.name}</h3><p>${item.summary}</p><small>${item.access}</small></article>`).join('')}</div>${panel('Pravilo dodele',`<div class="assignment-flow"><span>1</span><div><strong>Super admin bira poziciju</strong><small>Ne postoji otvorena registracija zaposlenih.</small></div><span>2</span><div><strong>Dodeljuje odgovornost i akciju</strong><small>Osoba vidi samo ono što joj je potrebno za rad.</small></div><span>3</span><div><strong>Pozivnica aktivira pristup</strong><small>Produkcija zahteva službeni identitet, MFA i audit.</small></div></div>`,'<p>Administrator upravlja svojim modulima, ali ne menja hijerarhiju prava</p>','full-span')}${panel('Poslednje promene',`<div class="audit-row"><strong>Danas 10:42</strong><span>Super admin</span><span>Promenio kapacitet akcije Dom omladine sa 36 na 40.</span><small>Akcija A-204</small></div><div class="audit-row"><strong>Danas 10:18</strong><span>Dr Ivan Marković</span><span>Odobrio stručni sadržaj vodiča za prvo davanje.</span><small>Aktivnost S-118</small></div><div class="audit-row"><strong>Danas 09:55</strong><span>Super admin</span><span>Dodelio prijem Mariji Petrović za Dom omladine.</span><small>Pristup P-482</small></div>`,'<p>Ko, kada i šta je promenio</p>','full-span')}`,
  integrations:()=>`${portalHeader('SISTEMSKA VEZA','API i integracije','<button class="ghost-button" data-action="check-api-health">Proveri vezu</button><button class="primary-button compact" data-action="check-api-operations">Proveri tok prijema</button>')}<div class="portal-grid equal">${panel('Status veze',`${apiStatusMarkup()}<div class="api-endpoint"><code>${configuredApiBase||'API_BASE nije podešen'}</code><small>Za lokalni prikaz dodajte <code>?api=http://127.0.0.1:3333</code> na admin URL.</small></div><div class="warning-box" style="margin-top:14px">Čak i kada demo API odgovori, on ne sadrži produkcionu prijavu, stvarne evidencije ni medicinske podatke.</div>`,'<p>Kontrolisana demonstraciona veza</p>')}${panel('Ugovorene rute',`<ul class="route-list"><li><code>GET /v1/portal/dashboard</code><span>Zbirni operativni pregled</span></li><li><code>GET /v1/portal/operations</code><span>Status termina bez zdravstvenih podataka</span></li><li><code>GET /v1/portal/events</code><span>Akcije i termini</span></li><li><code>GET /v1/portal/audit</code><span>Trag promena</span></li><li><code>POST /v1/staff/invitations</code><span>Demo pozivnica osoblju — bez slanja e-pošte</span></li></ul><button class="secondary-button" data-action="show-api-boundaries">Pogledaj granice pristupa</button>`,'<p>Produkcione rute čekaju odobrenje Zavoda</p>')}</div>${panel('Šta se aktivira kasnije',`<div class="integration-grid"><article><strong>Prijava zaposlenih</strong><span>SSO/MFA, dodela smene i opoziv uređaja</span></article><article><strong>Akcije i zalihe</strong><span>Samo potvrđen izvor, vlasništvo nad podacima i audit</span></article><article><strong>Medicinski tok</strong><span>Odvojen sistem i pravila Zavoda — nikad deo admin portala</span></article></div>`,'<p>Ove granice čuvamo i u prototipu</p>','full-span')}`
};

portalTemplates.checkin=()=>`${portalHeader('PRIJEM DAVALACA','Odvojeni radni prostor','<span class="header-context">Dodeljena smena · samo prijem</span>')}<div class="portal-grid equal">${panel('Šta radi prijem',`<div class="task-row"><span class="task-icon">1</span><div><strong>Pronalazi tačnu rezervaciju</strong><small>QR kod ili broj rezervacije, zatim proverava identitet sa ličnom kartom.</small></div></div><div class="task-row"><span class="task-icon">2</span><div><strong>Proverava podatke dodeljene smene</strong><small>Ime i prezime, datum rođenja, JMBG i evidentirana ABO/RhD grupa.</small></div></div><div class="task-row"><span class="task-icon">3</span><div><strong>Evidentira dolazak jednom</strong><small>Medicinski tim potom otvara zaseban odobreni tok.</small></div></div>`,'<p>Prijem ne vidi istoriju, upitnik, nalaze niti procenu podobnosti. Krvna grupa je evidencioni podatak, ne medicinska odluka.</p>')}${panel('Šta se dešava posle prijema',`<div class="task-row"><span class="task-icon neutral">✓</span><div><strong>Portal prima samo zbirni status</strong><small>Koordinator vidi broj prijavljenih i nedolaske, bez detalja identiteta ili zdravlja.</small></div></div><div class="task-row"><span class="task-icon neutral">↗</span><div><strong>Medicinski tim preuzima osobu</strong><small>Klinički karton se otvara u zasebnom, zaštićenom radnom prostoru.</small></div></div><div class="info-box" style="margin-top:14px">Za skeniranje, ručnu pretragu i evidenciju dolaska koristi se isključivo aplikacija „Kapi Života — Prijem“.</div>`,'<p>Prijem nema prečicu do operativnog portala niti do medicinskog kartona</p>')}</div>`;

portalTemplates.content=()=>`${portalHeader('PR I SADRŽAJ','Profesionalna redakcija','<button class="ghost-button" data-action="open-content-calendar">Kalendar objava</button><button class="primary-button compact" data-action="create-news">+ Nova vest</button>')}<div class="content-command"><div><span class="small-label">REDACIJSKI CENTAR</span><h2>Od nacrta do stručno odobrene objave</h2><p>PR priprema sadržaj, stručna služba proverava medicinske tvrdnje, a objavu odobrava odgovorna osoba. Svaka verzija i izmena ostaju u auditu.</p></div><div class="content-command-actions"><button class="table-button" data-action="open-content-library">Biblioteka medija</button><button class="table-button" data-action="open-content-analytics">Učinak objava</button></div></div><div class="content-metrics">${metric('Nacrti','4','čekaju uređivanje')}${metric('Stručna provera','2','potrebna potvrda')}${metric('Zakazano','3','sledećih 7 dana')}${metric('Objavljeno','28','ovog meseca',true)}</div>${panel('Radna tabla sadržaja',`<div class="content-board">${portalNews.map(item=>`<article class="news-work-card" data-action="open-news-editor" data-news="${item.id}"><div class="news-work-top"><span class="small-label">${item.type}</span>${pill(item.status,item.tone)}</div><h3>${item.title}</h3><p>${item.summary}</p><div class="news-work-meta"><span>${item.author}</span><span>${item.updated}</span></div><div class="news-reviewer">${item.reviewer}</div><button class="table-button" data-action="open-news-editor" data-news="${item.id}">Otvori urednik</button></article>`).join('')}</div>`,'<p>Svaka kartica otvara urednik sa verzijama, recenzijom i objavom</p>','full-span')}`;
portalTemplates.medical=()=>`${portalHeader('MEDICINSKA SLUŽBA','Klinički radni prostor','<button class="ghost-button" data-action="medical-audit">Pristupni audit</button><button class="primary-button compact" data-action="refresh-medical-worklist">Osveži listu</button>')}<div class="medical-boundary"><span class="medical-boundary-mark">+</span><div><strong>Zaštićen medicinski radni tok</strong><p>Ovo je demonstracioni prikaz sintetičkih zapisa. U produkciji medicinska služba i Super admin vide objedinjeni tok samo uz službenu prijavu, MFA, razlog pristupa i neizmenjiv audit.</p></div><button class="table-button" data-action="medical-access-policy">Pravila pristupa</button></div><div class="medical-metrics">${metric('Čeka pregled',medicalVisits.filter(item=>item.status==='Čeka pregled').length,'primljeni na prijemu')}${metric('U pregledu',medicalVisits.filter(item=>item.status==='U pregledu').length,'aktivan lekar')}${metric('Ishod evidentiran',medicalVisits.filter(item=>item.status==='Ishod evidentiran').length,'danas')}${metric('Audit pristupa','100%','demo zapis')}</div>${panel('Današnja medicinska lista',`<div class="medical-worklist">${medicalVisits.map(visit=>`<article class="medical-visit-card" data-action="open-medical-visit" data-visit="${visit.id}"><span class="staff-avatar">${visit.initials}</span><div><strong>${visit.name}</strong><small>${visit.reference} · termin ${visit.time} · prijem ${visit.checkIn}</small><p>${visit.history}</p></div><div>${pill(visit.status,visit.tone)}<button class="table-button" data-action="open-medical-visit" data-visit="${visit.id}">Otvori karton</button></div></article>`).join('')}</div>`,'<p>Lista objedinjuje termin, prijem i postojeći medicinski radni tok — bez javnog ili PR pristupa</p>','full-span')}`;
portalTemplates['qr-access']=()=>`${portalHeader('SUPER ADMIN','Pozivnice i QR pristup','<button class="ghost-button" data-portal-screen="staff">Osoblje</button><button class="primary-button compact" data-action="create-staff-invite">+ Nova pozivnica</button>')}<div class="super-admin-callout"><span class="super-admin-mark">QR</span><div><strong>Pristup je ličan, vremenski ograničen i vezan za poziciju</strong><p>Super admin generiše jednokratnu QR pozivnicu tek nakon što postavi poziciju, odgovornost, ustanovu i akciju. QR nije zajednički nalog i nikada ne otkriva podatke davaoca.</p></div><button class="table-button" data-action="open-super-admin">Pravila Super admina</button></div><div class="portal-grid equal">${panel('Aktivna demonstraciona pozivnica',`<div class="portal-qr-card"><div>${qrCode()}<small>INV-KZ-PRIJEM-1026</small></div><div><span class="small-label">OSOBLJE NA PRIJEMU</span><h3>Dom omladine · Prijem 1</h3><p>Važi do 18:00 danas. Aktivacija u produkciji traži službenu e-poštu, potvrdu identiteta i MFA.</p><div class="button-row"><button class="primary-button compact" data-action="generate-portal-qr">Generiši novi QR</button><button class="ghost-button" data-action="revoke-portal-qr">Opozovi</button></div></div></div>`,'<p>QR samo pokreće kontrolisanu aktivaciju naloga</p>')}${panel('Kontrole pristupa',`<div class="task-row"><span class="task-icon">1</span><div><strong>Pozicija i odgovornost</strong><small>Svaki pristup je ograničen na posao, ustanovu i akciju.</small></div><button class="table-button" data-portal-screen="staff">Proveri</button></div><div class="task-row"><span class="task-icon neutral">2</span><div><strong>Uređaji i sesije</strong><small>Super admin može opozvati uređaj ili aktivnu sesiju.</small></div><button class="table-button" data-action="manage-sessions">Upravljaj</button></div><div class="task-row"><span class="task-icon neutral">3</span><div><strong>Audit</strong><small>Prijava, promena prava i medicinski pristup imaju zaseban trag.</small></div><button class="table-button" data-action="medical-audit">Pregled</button></div>`,'<p>Produkcija zahteva autentifikaciju Zavoda i odobrene bezbednosne politike</p>')}</div>`;
portalTemplates.access=()=>`${portalHeader('UPRAVLJANJE PRISTUPOM','Matrica uloga i radnih prostora','<button class="ghost-button" data-portal-screen="qr-access">QR pozivnice</button><button class="primary-button compact" data-action="create-staff-invite">+ Nova pozivnica</button>')}<div class="role-grid role-grid-wide">${roleCatalog.map(item=>`<article class="role-card ${item.role==='super_admin'?'super-admin-card':''}" data-action="open-role-workspace" data-role="${item.role}" tabindex="0"><span class="small-label">${item.role}</span><h3>${item.name}</h3><p>${item.summary}</p><small>${item.access}</small><button class="table-button" data-action="open-role-workspace" data-role="${item.role}">Otvori radni prostor</button></article>`).join('')}</div>${panel('Pravilo dodele',`<div class="assignment-flow"><span>1</span><div><strong>Super admin bira poziciju</strong><small>Ne postoji otvorena registracija zaposlenih.</small></div><span>2</span><div><strong>Dodeljuje odgovornost i akciju</strong><small>Osoba vidi samo ono što joj je potrebno za rad.</small></div><span>3</span><div><strong>Pozivnica aktivira pristup</strong><small>Produkcija zahteva službeni identitet, MFA i audit.</small></div></div>`,'<p>Svaka uloga vodi u sopstveni radni prostor; administrator ne može menjati hijerarhiju prava</p>','full-span')}`;
portalTemplates.command=()=>`${portalHeader('OPERATIVNI CENTAR','Dnevni prioriteti','<button class="ghost-button" data-action="refresh-command-center">Osveži</button><button class="primary-button compact" data-portal-screen="approvals">Otvori odobravanja</button>')}<div class="command-hero"><div><span class="small-label">DOM OMLADINE · DAN AKCIJE</span><h2>Kontrola toka, odluka i odgovornosti</h2><p>Jedno mesto za predstojeće odluke. Operativni, sadržajni i pristupni zadaci ne mešaju medicinske podatke.</p></div><div class="command-score"><strong>4</strong><span>prioriteta</span></div></div><div class="command-grid">${portalAlerts.map(item=>`<article class="command-card ${item.tone}" data-action="open-alert" data-alert="${item.id}"><span class="small-label">${item.type}</span><h3>${item.title}</h3><p>${item.detail}</p><button class="table-button" data-action="open-alert" data-alert="${item.id}">Otvori zadatak</button></article>`).join('')}</div>${panel('Tok akcije · Dom omladine',`<div class="action-timeline"><article><span>1</span><div><strong>Pre akcije</strong><small>Kapacitet, osoblje, komunikacije i odobreni sadržaj.</small></div><button class="table-button" data-portal-screen="events">Akcija</button></article><article><span>2</span><div><strong>Prijem</strong><small>Rezervacija, identitet i dolazak — bez medicinske istorije.</small></div><button class="table-button" data-portal-screen="operations">Tok</button></article><article><span>3</span><div><strong>Medicinska služba</strong><small>Zaštićen tok i audit pristupa.</small></div><button class="table-button" data-portal-screen="medical">Medicinski rad</button></article><article><span>4</span><div><strong>Završetak akcije</strong><small>Zbirni rezultat, izveštaj i post-akcijska podrška.</small></div><button class="table-button" data-portal-screen="reports">Izveštaj</button></article></div>`,'<p>Svaka faza ima vlasnika, dozvolu i trag promene</p>','full-span')}`;
