portalTemplates.organization=()=>`${portalHeader('MREŽA ZAVODA','Ustanove, lokacije i smene','<button class="ghost-button" data-action="open-location-map">Mapa ustanova</button><button class="primary-button compact" data-action="create-location">+ Nova lokacija</button>')}<div class="organization-banner"><div><span class="small-label">OPERATIVNA MREŽA</span><h2>Svaka akcija ima lokaciju, smenu, kapacitet i odgovorno osoblje</h2><p>Prijem i medicinska služba vide samo dodeljenu ustanovu i aktivnu smenu. Koordinator upravlja operativnim rasporedom, a Super admin dodeljuje pristup.</p></div><button class="table-button" data-action="open-staff-schedule">Otvori raspored</button></div><div class="organization-grid"><article class="organization-card"><span class="small-label">CENTRALNA USTANOVA</span><h3>Institut za transfuziju</h3><p>3 aktivne akcije · 2 medicinska tima</p><button class="table-button" data-action="open-facility">Upravljaj</button></article><article class="organization-card aqua"><span class="small-label">MOBILNA AKCIJA</span><h3>Dom omladine</h3><p>Prijem 1 · 10:00–14:00 · kapacitet 40</p><button class="table-button" data-action="open-shift">Otvori smenu</button></article><article class="organization-card amber"><span class="small-label">SLEDEĆA AKCIJA</span><h3>Studentski kulturni centar</h3><p>19. septembar · čeka potvrdu osoblja</p><button class="table-button" data-action="assign-shift">Dodeli smenu</button></article></div>${panel('Kontrola smena',`<div class="assignment-flow"><span>1</span><div><strong>Koordinator predlaže raspored</strong><small>Osoblje, kapacitet, prostor i vreme akcije.</small></div><span>2</span><div><strong>Super admin potvrđuje pristup</strong><small>Pozicija, lokacija i uređaj su povezani.</small></div><span>3</span><div><strong>Smena se otvara na dan akcije</strong><small>Prijem i medicinska služba vide samo svoj radni kontekst.</small></div></div>`,'<p>Promena lokacije ili smene automatski traži proveru konflikta i audit</p>','full-span')}`;
portalTemplates.communications=()=>`${portalHeader('KOMUNIKACIJE','Šabloni, kanali i odobrenja','<button class="ghost-button" data-action="open-channel-policy">Pravila kanala</button><button class="primary-button compact" data-action="create-message-template">+ Novi šablon</button>')}<div class="communication-grid"><article class="communication-card wine"><span class="small-label">PUSH / SMS</span><h3>Podsetnik za termin</h3><p>Odobren šablon bez zdravstvenih podataka na zaključanom ekranu.</p><button class="table-button" data-action="edit-message-template">Uredi šablon</button></article><article class="communication-card aqua"><span class="small-label">JAVNA VEST</span><h3>Akcija u Domu omladine</h3><p>Naslovna slika, izvor, recenzent, objava i mobilni pregled.</p><button class="table-button" data-portal-screen="content">Otvori sadržaj</button></article><article class="communication-card amber"><span class="small-label">KAMPANJA</span><h3>Potreba za 0−</h3><p>Publika, limit učestalosti, talasi i odobrenje odgovorne osobe.</p><button class="table-button" data-portal-screen="campaign-detail">Otvori kampanju</button></article></div>${panel('Kontrola kvaliteta pre slanja',`<div class="task-row"><span class="task-icon">✓</span><div><strong>Jasna svrha i vlasnik</strong><small>Poruka pripada akciji, ustanovi i odgovornoj osobi.</small></div><button class="table-button" data-action="open-message-checklist">Pregled</button></div><div class="task-row"><span class="task-icon neutral">A</span><div><strong>Pristupačnost i jezik</strong><small>Čitljiv naslov, alt tekst slike, ćirilica/latinica i razumljiv ton.</small></div><button class="table-button" data-action="open-message-checklist">Pregled</button></div><div class="task-row"><span class="task-icon neutral">i</span><div><strong>Privatnost</strong><small>Bez krvne grupe, medicinske procene ili osetljivog razloga u obaveštenju.</small></div><button class="table-button" data-action="open-channel-policy">Pravila</button></div>`,'<p>PR uređuje sadržaj, dok sistem i stručna služba kontrolišu granice objave</p>')}`;
portalTemplates.governance=()=>`${portalHeader('KONTROLA I BEZBEDNOST','Incidenti, uređaji, audit i status sistema','<button class="ghost-button" data-action="open-system-health">Status sistema</button><button class="primary-button compact" data-action="report-incident">+ Prijavi incident</button>')}<div class="governance-grid"><article class="governance-card"><span class="governance-icon">!</span><div><span class="small-label">INCIDENTI</span><h3>2 otvorena zadatka</h3><p>Kasno ažuriranje zaliha i QR pozivnica pred istekom.</p><button class="table-button" data-action="open-incidents">Otvori incidente</button></div></article><article class="governance-card"><span class="governance-icon aqua">⌁</span><div><span class="small-label">UREĐAJI I SESIJE</span><h3>6 aktivnih uređaja</h3><p>1 uređaj čeka ponovnu MFA potvrdu.</p><button class="table-button" data-action="manage-sessions">Upravljaj uređajima</button></div></article><article class="governance-card"><span class="governance-icon green">✓</span><div><span class="small-label">SISTEMSKI STATUS</span><h3>4 od 5 provera spremno</h3><p>API integracija Zavoda još nije povezana.</p><button class="table-button" data-action="open-system-health">Detalji</button></div></article></div>${panel('Revizioni centar',`<div class="toolbar"><input class="search-input" placeholder="Pretraga izvršioca, akcije ili identifikatora"><select class="select-control"><option>Sve promene</option><option>Pristupi</option><option>Sadržaj</option><option>Akcije i termini</option><option>Medicinski audit</option></select><button class="primary-button compact" data-action="open-audit-search">Pretraži audit</button></div><div class="audit-row"><strong>Danas 10:42</strong><span>Super admin</span><span>Dodelio prijemnu smenu i pristup lokaciji.</span><small>Pristup P-482</small></div><div class="audit-row"><strong>Danas 10:18</strong><span>Dr Ivan Marković</span><span>Otvorio demonstracioni medicinski karton sa razlogom pregleda.</span><small>Medicinski audit M-118</small></div><div class="audit-row"><strong>Danas 09:55</strong><span>Ana Ilić</span><span>Poslala vodič na stručnu proveru.</span><small>Sadržaj S-482</small></div>`,'<p>Auditor čita ovaj centar, ali ne menja podatke; Super admin upravlja pravilima pristupa</p>','full-span')}`;
portalTemplates.hierarchy=()=>`${portalHeader('SISTEMSKA HIJERARHIJA','Pozicije, delegacije i granice odgovornosti','<button class="ghost-button" data-portal-screen="access">Matrica prava</button><button class="primary-button compact" data-portal-screen="qr-access">Upravljaj pristupom</button>')}<div class="hierarchy-notice"><span class="super-admin-mark">SA</span><div><strong>Super admin upravlja sistemskim pristupom, ali ne preuzima stručnu medicinsku odluku.</strong><p>Hijerarhija pristupa i stručna odgovornost su namerno odvojene: lekar donosi medicinsku odluku, PR uređuje javni sadržaj, koordinator vodi akciju, a Super admin dodeljuje i nadzire sistemska ovlašćenja.</p></div></div><div class="hierarchy-tree"><article class="hierarchy-root"><span>Super admin Zavoda</span><strong>Svi sistemi, ustanove, pozicije, delegacije, MFA i audit</strong><button class="table-button" data-action="open-super-admin">Ovlašćenja</button></article><div class="hierarchy-branches"><article><span class="hierarchy-label">Sistemska delegacija</span><h3>Administrator</h3><p>Konfiguracija, nalozi i bezbednosni događaji u dodeljenom obimu.</p><small>Ne menja hijerarhiju niti medicinska prava.</small></article><article><span class="hierarchy-label">Operativna odgovornost</span><h3>Koordinator akcija</h3><p>Akcije, kapaciteti, smene, logistika i tok prijema.</p><small>Ne vidi medicinski karton.</small></article><article class="clinical"><span class="hierarchy-label">Stručna nezavisnost</span><h3>Medicinski rukovodilac</h3><p>Medicinski postupak, lekarski tim i stručna provera sadržaja.</p><small>Klinička odluka nije delegirana administratoru.</small></article><article><span class="hierarchy-label">Javna komunikacija</span><h3>PR i sadržaj</h3><p>Vesti, vodiči, mediji i kampanje uz obaveznu proveru.</p><small>Ne vidi zdravstvene i identifikacione podatke.</small></article><article><span class="hierarchy-label">Izvršenje na akciji</span><h3>Prijem</h3><p>Identitet, rezervacija, dolazak i nedolazak na dodeljenoj smeni.</p><small>Ne vidi medicinsku istoriju.</small></article><article><span class="hierarchy-label">Nezavisan nadzor</span><h3>Revizor</h3><p>Audit, zbirni izveštaji i kontrola primene pravila.</p><small>Nema mogućnost izmene.</small></article></div></div>${panel('Pravilo delegacije',`<div class="info-box">Super admin dodeljuje ulogu, ustanovu, akciju, rok i uređaj. Delegirana osoba dobija samo najmanji potreban obim. Medicinski rukovodilac može odobravati stručni sadržaj i klinički postupak, ali ne menja sistemske pristupe. Svako izuzeće ima razlog, rok i audit.</div>`,'<p>Ova struktura sprečava koncentraciju neprimerenih prava kod jedne operativne uloge</p>','full-span')}`;

const portalMetricRoute={Zakazano:'operations',Prijavljeni:'operations','Kod medicinskog tima':'medical',Kapacitet:'events','Aktivne sesije':'governance',Pozivnice:'qr-access','Otvoreni incidenti':'governance','Aktivni tok':'operations','Sledeća odluka':'approvals','Čeka prijem':'operations','Nisu došli':'operations','Čeka pregled':'medical','U pregledu':'medical','Evidentiran ishod':'medical','Audit pristupa':'governance',Nacrti:'content','Stručna provera':'approvals',Objavljeno:'content',Izveštaji:'reports'};
function premiumMetric(label,value,detail,tone='wine',trend=''){const route=portalMetricRoute[label]||'reports';return `<button class="premium-metric ${tone} interactive-card" data-portal-screen="${route}" aria-label="${label}: ${value}. Otvori povezani radni prostor"><div class="premium-metric-top"><span>${label}</span>${trend?`<b>${trend}</b>`:''}</div><strong>${value}</strong><small>${detail}</small><i></i></button>`}
const portalActionGlyphs={dashboard:'▦',command:'◉',approvals:'✓',organization:'⌂',communications:'✉',governance:'◈',events:'▣',checkin:'⌖',operations:'↔',medical:'✚',campaigns:'◌',donors:'◎',inventory:'◒',content:'▤',reports:'▥',staff:'♙','qr-access':'▦',hierarchy:'⌘',access:'◈',integrations:'⌁','open-location-map':'⌖','center-portal-map':'⌖','open-facility':'⌂','open-shift':'◷','assign-shift':'＋','open-staff-schedule':'◷','create-location':'＋','create-event':'＋','create-news':'＋','refresh-operations':'↻','refresh-command-center':'↻','refresh-medical-worklist':'↻','open-content-library':'▤','open-content-analytics':'▥','open-content-calendar':'◷','medical-audit':'◈','medical-access-policy':'◈','open-system-health':'◉','report-incident':'!','open-portal-profile':'◎','export-report':'⇣'};
function decoratePortalActions(){if(!isAdminEntry)return;$$("#portal-screen button[data-action], #portal-screen button[data-portal-screen]").forEach(button=>{if(button.classList.contains('table-button')){if(!button.querySelector('.button-arrow')){button.innerHTML=button.innerHTML.replace(/→/g,'').trim();button.insertAdjacentHTML('beforeend','<span class="button-arrow" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 12h13M13 7l5 5-5 5"/></svg></span>')}return}if(button.matches('.dashboard-kpi,.dashboard-icon-button,.dashboard-open-action,.dashboard-map-footer button,.dashboard-priority-row,.journey-steps article>button,.premium-metric,.flow-status button,.quality-row,.quality-checks button,.checkin-row')||button.querySelector('.action-icon'))return;const glyph=portalActionGlyphs[button.dataset.action||button.dataset.portalScreen];if(!glyph)return;button.classList.add('has-action-icon');button.insertAdjacentHTML('afterbegin',`<span class="action-icon" aria-hidden="true">${glyph}</span>`)});$$('#portal-screen .signal-card,.role-task-card,.organization-card,.communication-card,.governance-card,.command-card').forEach(card=>{if(card.dataset.portalScreen||card.dataset.action)return;const target=card.querySelector('[data-portal-screen],[data-action]');if(!target)return;const key=target.dataset.portalScreen?'portalScreen':'action';card.dataset[key]=target.dataset[key];card.setAttribute('tabindex','0');card.setAttribute('role','button');card.classList.add('clickable-card')})}
function roleWorkspaceStrip(){const workspace=roleWorkspaces[state.activePortalRole]||roleWorkspaces.super_admin;if(state.activePortalRole==='super_admin')return '';return `<aside class="role-workspace-strip"><span class="role-workspace-mark">${workspace.name.split(' ').map(word=>word[0]).join('').slice(0,2)}</span><div><small>RADNI PROSTOR · ${workspace.name.toUpperCase()}</small><strong>${workspace.scope}</strong></div><button class="table-button" data-action="exit-role-preview">Vrati Super admin</button></aside>`}
function showPortalLoading(screen,label='Osvežavamo podatke…'){portalScreen.innerHTML=`<section class="portal-skeleton" aria-live="polite"><span>${label}</span><div class="skeleton-hero"></div><div class="skeleton-grid"><i></i><i></i><i></i><i></i></div><div class="skeleton-panel"></div></section>`;setTimeout(()=>renderPortal(screen),520)}
const dashboardSignals=[
  {tone:'mint',label:'Prijem',title:'6 osoba u aktivnom toku',text:'3 prijavljene · 3 kod medicinskog tima',screen:'operations',button:'Otvori tok'},
  {tone:'amber',label:'Odluka danas',title:'2 stavke čekaju vlasnika',text:'Smene i stručna provera sadržaja',screen:'approvals',button:'Pregledaj'},
  {tone:'coral',label:'Komunikacije',title:'Podsetnik čeka odobrenje',text:'Provereni kapacitet pre slanja',screen:'communications',button:'Otvori'},
];
portalTemplates.dashboard=()=>{const counts=intakeCounts();const completed=counts.checkedIn+counts.medical;const capacity=Math.round((completed/adminIntakeRows.length)*100);return `${portalHeader('OPERATIVNI DEMO · DOM OMLADINE','Dobro jutro, Ivana','<button class="ghost-button" data-portal-screen="command">Dnevni centar</button><button class="primary-button compact" data-portal-screen="events">+ Nova akcija</button>')}<section class="premium-dashboard-hero"><div class="hero-orb one"></div><div class="hero-orb two"></div><div class="premium-hero-copy"><span class="eyebrow">DAN AKCIJE · 12. OKTOBAR</span><h2>Jedan miran pregled<br>svake važne odluke.</h2><p>Operativa, ljudi, kapacitet i sadržaj su povezani, ali medicinski tok ostaje zaštićen i odvojen.</p><div class="hero-action-row"><button class="primary-button" data-portal-screen="operations">Otvori tok prijema</button><button class="hero-text-button" data-portal-screen="organization">Ustanove i smene <span>→</span></button></div></div><div class="hero-action-status"><div class="action-status-head"><span class="live-status"><i></i> Akcija u toku</span><button class="icon-circle" data-action="open-facility" aria-label="Detalji akcije">↗</button></div><h3>Dom omladine</h3><p>10:00–14:00 · Prijem 1</p><div class="capacity-ring"><div><strong>${capacity}%</strong><small>aktivnog toka</small></div></div><div class="status-foot"><span><b>${counts.scheduled}</b> čeka prijem</span><span><b>${counts.medical}</b> kod tima</span></div></div></section><section class="premium-metrics-grid">${premiumMetric('Zakazano',counts.scheduled,'čeka potvrdu dolaska','wine','danas')}${premiumMetric('Prijavljeni',counts.checkedIn,'u redu za medicinski tim','aqua','uživo')}${premiumMetric('Kod medicinskog tima',counts.medical,'logistički predato','mint','aktivno')}${premiumMetric('Kapacitet',`${capacity}%`,'današnji tok prijema','amber','13 termina')}</section><section class="signal-grid">${dashboardSignals.map(signal=>`<article class="signal-card ${signal.tone}"><span>${signal.label}</span><h3>${signal.title}</h3><p>${signal.text}</p><button class="table-button" data-portal-screen="${signal.screen}">${signal.button} <b>→</b></button></article>`).join('')}</section><section class="dashboard-lower-grid"><section class="premium-panel map-command-panel"><div class="premium-panel-head"><div><span class="eyebrow">MREŽA I LOKACIJE</span><h2>Današnji radni kontekst</h2></div><button class="table-button" data-action="open-location-map">Otvori mapu</button></div><div class="portal-map-visual"><div class="map-grid-lines"></div><span class="map-route route-a"></span><span class="map-route route-b"></span><button class="portal-map-pin selected" data-action="open-facility" style="left:36%;top:43%"><b>●</b><small>Dom omladine</small></button><button class="portal-map-pin aqua" data-action="open-facility" style="left:68%;top:26%"><b>●</b><small>Institut</small></button><button class="portal-map-pin amber" data-action="open-facility" style="left:70%;top:67%"><b>●</b><small>SKC</small></button><div class="map-context-card"><span class="live-status"><i></i> Aktivan punkt</span><strong>Dom omladine · Prijem 1</strong><small>40 mesta · 2 medicinska tima · 6 aktivnih poseta</small></div></div></section><section class="premium-panel priority-panel"><div class="premium-panel-head"><div><span class="eyebrow">PRIORITETI</span><h2>Šta traži pažnju</h2></div><button class="table-button" data-portal-screen="command">Sve radnje</button></div><div class="priority-stack">${portalAlerts.slice(0,3).map((alert,index)=>`<button class="priority-row" data-action="open-alert" data-alert="${alert.id}"><span class="priority-number ${alert.tone}">0${index+1}</span><span><b>${alert.title}</b><small>${alert.detail}</small></span><em>→</em></button>`).join('')}</div></section></section><section class="activity-rail"><div><div><span class="eyebrow">TOK DANA</span><h2>Od pripreme do zatvaranja akcije</h2></div><button class="table-button" data-portal-screen="reports">Izveštaji</button></div><div class="activity-steps"><article class="done"><span>✓</span><div><b>Priprema</b><small>Smene i kapacitet potvrđeni</small></div></article><article class="active"><span>2</span><div><b>Prijem</b><small>${completed} osoba u aktivnom toku</small></div></article><article><span>3</span><div><b>Medicinski tim</b><small>Zaštićen zaseban radni prostor</small></div></article><article><span>4</span><div><b>Zatvaranje</b><small>Zbirni rezultat i audit</small></div></article></div></section>`};

