const operationContexts=[
  {id:'dom-omladine',name:'Dom omladine',city:'Beograd',date:'19. septembar · 10:00–14:00',state:'U toku',tone:'success',scope:'Prijem 1 · 13 termina · aktivna smena'},
  {id:'skc',name:'Studentski kulturni centar',city:'Novi Sad',date:'19. septembar · 12:00–16:00',state:'Planirano',tone:'info',scope:'Prijem čeka dodelu · 36 mesta'},
  {id:'dunav',name:'Kompanija Dunav',city:'Zemun',date:'12. septembar · završeno',state:'Završeno',tone:'neutral',scope:'Zbirni izveštaj spreman · 30 mesta'}
];
function activeOperation(){return operationContexts.find(item=>item.id===state.selectedOperation)||operationContexts[0]}
function portalCalendar(){const weekday=['PON','UTO','SRE','ČET','PET','SUB','NED'];const cells=[...Array(6).fill(''),...Array.from({length:30},(_,i)=>String(i+1)),...Array(6).fill('')].slice(0,42);return `<section class="events-calendar-shell"><div class="calendar-month-head"><div><span class="eyebrow">SEPTEMBAR 2026.</span><h2>Kalendar akcija</h2><p>Izaberi datum: lista ispod prikazuje samo akcije za taj dan.</p></div><button class="table-button" data-action="select-portal-day" data-day="">Sve akcije</button></div><div class="calendar-weekdays">${weekday.map(day=>`<span>${day}</span>`).join('')}</div><div class="month-grid">${cells.map(day=>{const count=portalEvents.filter(event=>portalEventDay(event)===day).length;return day?`<button class="month-day ${state.selectedPortalDay===day?'active':''} ${count?'has-event':''}" data-action="select-portal-day" data-day="${day}"><strong>${day}</strong>${count?`<small>${count} akcija</small>`:'<small>—</small>'}</button>`:'<span class="month-day empty"></span>'}).join('')}</div></section>`}
function eventTable(){const rows=filteredEvents();const title=state.selectedPortalDay?`Akcije · ${state.selectedPortalDay}. septembar`:'Sve akcije i termini';return panel(title,`<div class="toolbar"><input class="search-input" data-portal-filter="events-query" value="${state.eventQuery}" placeholder="Pretraži naziv, mesto ili organizatora"><select class="select-control" data-portal-filter="events-municipality"><option value="all">Sve opštine</option><option value="Beograd" ${state.eventMunicipality==='Beograd'?'selected':''}>Beograd</option><option value="Novi Sad" ${state.eventMunicipality==='Novi Sad'?'selected':''}>Novi Sad</option><option value="Zemun" ${state.eventMunicipality==='Zemun'?'selected':''}>Zemun</option></select><select class="select-control" data-portal-filter="events-status"><option value="all">Svi statusi</option><option value="U toku" ${state.eventStatus==='U toku'?'selected':''}>U toku</option><option value="Objavljeno" ${state.eventStatus==='Objavljeno'?'selected':''}>Objavljeno</option><option value="Nacrt" ${state.eventStatus==='Nacrt'?'selected':''}>Nacrt</option></select></div><table class="data-table"><thead><tr><th>Akcija</th><th>Datum i vreme</th><th>Pristup</th><th>Popunjenost</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(portalEventRow).join('')||'<tr><td colspan="6" class="empty-table">Nema akcija za izabrani datum i filtere.</td></tr>'}</tbody></table>`,'<p>Datum u kalendaru, pretraga i filteri koriste isti demonstracioni skup</p>','table-panel premium-table-panel')}
portalTemplates.events=()=>`${portalHeader('AKCIJE I TERMINI','Kalendar i raspored','<button class="ghost-button" data-action="import-schedule">Uvezi raspored</button><button class="primary-button compact" data-action="create-event">+ Nova akcija</button>')}${portalCalendar()}${eventTable()}`;
portalTemplates.checkin=()=>{const rows=adminIntakeRows.slice(0,7);return `${portalHeader('PRIJEM DAVALACA','Radni pregled dolazaka','<button class="ghost-button" data-action="open-reception-app">Otvori aplikaciju prijema</button><button class="primary-button compact" data-portal-screen="operations">Operativni tok</button>')}<section class="checkin-command"><div><span class="eyebrow">DOM OMLADINE · PRIJEM 1</span><h2>Zakazani dolasci za aktivnu smenu</h2><p>Prijem potvrđuje rezervaciju i identitet. Medicinske podatke, procene i obrasce ne prikazuje portal.</p></div><div class="checkin-command-stat"><strong>${rows.length}</strong><span>zakazanih termina</span><small>10:00–14:00 · Beograd</small></div></section><section class="checkin-layout"><section class="premium-panel checkin-queue"><header class="premium-panel-head"><div><span class="eyebrow">DANAŠNJI RED</span><h2>Pripremljeni za prijem</h2></div><button class="table-button" data-portal-screen="operations">Prikaži statuse</button></header><div class="checkin-list">${rows.map((row,index)=>`<button class="checkin-row" data-action="open-intake-record" data-reservation="${row[2]}"><span class="checkin-order">${String(index+1).padStart(2,'0')}</span><span class="staff-avatar">${row[1]}</span><span><strong>${row[0]}</strong><small>${row[2]} · termin ${row[3]}</small></span>${pill(row[4],statusTone(row[4]))}<b>→</b></button>`).join('')}</div></section><aside class="checkin-side"><section><span class="checkin-icon">${dashboardGlyph('calendar')}</span><h3>Jedan jasan korak</h3><p>Pronađi QR ili broj rezervacije, proveri ličnu kartu i evidentiraj dolazak samo jednom.</p><button class="table-button" data-action="open-reception-app">Skeniraj QR</button></section><section><span class="checkin-icon">${dashboardGlyph('shield')}</span><h3>Granica pristupa</h3><p>Prijem vidi samo podatke dodeljene smene. Medicinska istorija nije deo ovog prostora.</p><button class="table-button" data-portal-screen="medical">Zaštićeni tok</button></section></aside></section>`};
portalTemplates.operations=()=>{const op=activeOperation(),isLive=op.id==='dom-omladine',counts=intakeCounts(),rows=isLive?filteredIntakeRows():[],completed=counts.checkedIn+counts.medical;return `${portalHeader(`${op.name.toUpperCase()} · ${op.state.toUpperCase()}`,'Operativni tok','<button class="ghost-button" data-action="open-operation-selector">Izaberi akciju</button><button class="primary-button compact" data-action="refresh-operations">Osveži tok</button>')}<section class="operations-hero"><div><span class="eyebrow">OPERATIVNI PREGLED · ${op.city.toUpperCase()}</span><h2>${op.name}: jasan tok, jedna odgovornost.</h2><p>${op.scope}. Promena statusa uvek vodi osobu samo u sledeći odgovarajući korak.</p><button class="hero-text-button demo-flow-button" data-action="open-operation-selector">Promeni radni kontekst <span>→</span></button></div><div class="operations-progress"><div><strong>${isLive?completed:'—'}</strong><span>${isLive?`od ${adminIntakeRows.length} u aktivnom toku`:op.state==='Planirano'?'akcija čeka početak':'akcija je zatvorena'}</span></div><div class="progress-track"><i style="width:${isLive?Math.round(completed/adminIntakeRows.length*100):op.state==='Planirano'?18:100}%"></i></div><small>${op.date}</small></div></section><section class="flow-status-grid">${[['01','Zakazano',counts.scheduled,'Čeka prijem','Zakazan','scheduled'],['02','Prijavljeno',counts.checkedIn,'Čeka medicinski tim','Prijavljen','checked'],['03','Kod tima',counts.medical,'Logistički predato','','medical'],['04','Nisu došli',counts.noShow,'Potrebna provera','Nije došao','no-show']].map(item=>`<article class="flow-status ${item[5]}"><span>${item[0]}</span><div><small>${item[1]}</small><strong>${isLive?item[2]:'—'}</strong><p>${item[3]}</p></div>${item[4]?`<button data-portal-filter="operations-status" data-status="${item[4]}">Lista →</button>`:'<button data-portal-screen="medical">Otvori →</button>'}</article>`).join('')}</section>${panel(isLive?'Današnji termini':'Radni kontekst akcije',isLive?`<div class="operations-toolbar"><div class="toolbar-search"><span>⌕</span><input class="search-input" data-portal-filter="operations-query" value="${state.operationsQuery}" placeholder="Pretraži ime ili broj rezervacije"></div><select class="select-control" data-portal-filter="operations-status"><option value="all">Svi statusi</option><option value="Zakazan" ${state.operationsStatus==='Zakazan'?'selected':''}>Zakazano</option><option value="Prijavljen" ${state.operationsStatus==='Prijavljen'?'selected':''}>Prijavljeni</option><option value="Kod tima" ${state.operationsStatus==='Kod tima'?'selected':''}>Kod medicinskog tima</option><option value="Nije došao" ${state.operationsStatus==='Nije došao'?'selected':''}>Nisu došli</option></select><span class="result-count">${rows.length} od ${adminIntakeRows.length} termina</span></div><div class="operations-table-wrap"><table class="data-table operations-table"><thead><tr><th>Davalac i rezervacija</th><th>Termin</th><th>Operativni status</th><th></th></tr></thead><tbody>${rows.map(intakeRow).join('')||'<tr><td colspan="4" class="empty-table">Nema termina koji odgovaraju izabranom filteru.</td></tr>'}</tbody></table></div>`:`<div class="empty-workspace"><span>${dashboardGlyph(op.state==='Planirano'?'calendar':'chart')}</span><h3>${op.state==='Planirano'?'Akcija još nema aktivan red prijema.':'Akcija je završena; aktivni red je zatvoren.'}</h3><p>Izaberite drugu akciju za rad uživo ili otvorite njen raspored i zbirni izveštaj.</p><button class="primary-button compact" data-action="open-operation-selector">Izaberi akciju</button></div>`,'<p>Operativni prikaz koristi sintetičke podatke; zdravstveni sadržaj je odvojen.</p>','table-panel premium-table-panel')}`};
portalTemplates.command=()=>`${portalHeader('OPERATIVNI CENTAR','Dnevni prioriteti','<button class="ghost-button" data-action="refresh-command-center">Osveži</button><button class="primary-button compact" data-portal-screen="approvals">Otvori odobravanja</button>')}<section class="command-hero"><div><span class="eyebrow">OPERATIVNI CENTAR · 12. OKTOBAR</span><h2>Odluke koje imaju vlasnika i sledeći korak.</h2><p>Kapacitet, sadržaj, pristup i zalihe ostaju odvojeni od medicinskih podataka — bez vizuelne buke.</p></div><div class="command-score"><strong>4</strong><span>otvorena prioriteta</span><button class="table-button" data-portal-screen="approvals">Pregledaj</button></div></section><section class="command-grid">${portalAlerts.map((item,index)=>`<article class="command-card ${item.tone}" data-action="open-alert" data-alert="${item.id}"><span class="command-card-icon">${dashboardGlyph(index===0?'shield':index===1?'chart':index===2?'calendar':'medical')}</span><div><span class="small-label">${item.type}</span><h3>${item.title}</h3><p>${item.detail}</p></div><button class="table-button" data-action="open-alert" data-alert="${item.id}">Otvori zadatak</button></article>`).join('')}</section>${panel('Operativna putanja',`<div class="action-timeline">${[['1','Pre akcije','Kapacitet, smene, javna objava i dozvole.','events','Raspored'],['2','Prijem','Rezervacija i dolazak u odvojenom radnom prostoru.','operations','Operativni tok'],['3','Medicinski rad','Zaštićeni klinički radni red aktivne smene.','medical','Medicinski tok'],['4','Završetak','Zbirni rezultat, izveštaj i audit promena.','reports','Izveštaj']].map(item=>`<article><span>${item[0]}</span><div><strong>${item[1]}</strong><small>${item[2]}</small></div><button class="table-button" data-portal-screen="${item[3]}">${item[4]}</button></article>`).join('')}</div>`,'<p>Svaka faza vodi u svoj radni prostor, bez preklapanja dozvola.</p>','full-span')}`;
const qualityTopics={purpose:{title:'Jasna svrha i vlasnik',icon:'shield',copy:'Svaka poruka ima akciju, ustanovu, odgovornu osobu i proverljiv razlog slanja.',checks:['Vlasnik je imenovan','Akcija i rok su povezani','Poruka ima jasan sledeći korak']},accessibility:{title:'Pristupačnost i jezik',icon:'chart',copy:'Objava je čitljiva, razumljiva i dostupna na svim predviđenim kanalima.',checks:['Naslov opisuje sadržaj','Slika ima alt tekst','Jezik i ton su provereni']},privacy:{title:'Privatnost komunikacije',icon:'medical',copy:'Javna i zaključana obaveštenja nikada ne otkrivaju medicinske ili lične podatke.',checks:['Nema osetljivih podataka','Kanal je primeren sadržaju','Učestalost i saglasnost su proverene']}};
portalTemplates.communications=()=>`${portalHeader('KOMUNIKACIJE','Kanali, šabloni i provere','<button class="ghost-button" data-portal-screen="quality">Standard kvaliteta</button><button class="primary-button compact" data-action="create-message-template">+ Novi šablon</button>')}<section class="communication-grid premium-communication-grid">${[['PUSH / SMS','Podsetnik za termin','Odobren šablon za naredni termin, bez osetljivih podataka.','calendar','wine','edit-message-template','Uredi šablon'],['JAVNA VEST','Akcija u Domu omladine','Naslovna slika, izvor, recenzent i mobilni pregled pre objave.','chart','aqua','content','Otvori sadržaj'],['KAMPANJA','Potreba za 0−','Publika, učestalost, kapacitet i odobrenje odgovorne osobe.','shield','amber','campaign-detail','Otvori kampanju']].map(item=>`<article class="communication-card ${item[4]}"><span class="communication-icon">${dashboardGlyph(item[3])}</span><div><span class="small-label">${item[0]}</span><h3>${item[1]}</h3><p>${item[2]}</p></div><button class="table-button" ${item[5]==='content'||item[5]==='campaign-detail'?`data-portal-screen="${item[5]}"`:`data-action="${item[5]}"`}>${item[6]}</button></article>`).join('')}</section>${panel('Standard kvaliteta pre slanja',`<div class="quality-list">${Object.entries(qualityTopics).map(([key,item],index)=>`<button class="quality-row" data-action="open-quality" data-quality="${key}"><span class="quality-row-icon">${dashboardGlyph(item.icon)}</span><span><small>0${index+1} · KONTROLA</small><strong>${item.title}</strong><em>${item.copy}</em></span><b>→</b></button>`).join('')}</div>`,'<p>Svaka provera otvara zasebnu radnu stranicu sa obaveznim stavkama.</p>','full-span premium-quality-panel')}`;
portalTemplates.quality=()=>{const item=qualityTopics[state.qualityTopic]||qualityTopics.purpose;return `${portalHeader('STANDARD KVALITETA',item.title,'<button class="ghost-button" data-portal-screen="communications">Nazad na komunikacije</button><button class="primary-button compact" data-action="open-message-checklist">Otvori proveru</button>')}<section class="quality-hero"><span>${dashboardGlyph(item.icon)}</span><div><span class="eyebrow">KONTROLNA TAČKA PRE OBJAVE</span><h2>${item.title}</h2><p>${item.copy}</p></div></section><section class="quality-workspace"><section class="premium-panel"><header class="premium-panel-head"><div><span class="eyebrow">OBAVEZNE STAVKE</span><h2>Provera pre slanja</h2></div><span class="quality-complete">3 stavke</span></header><div class="quality-checks">${item.checks.map((check,index)=>`<button data-action="open-message-checklist"><span>${String(index+1).padStart(2,'0')}</span><strong>${check}</strong><b>→</b></button>`).join('')}</div></section><aside class="quality-side-note"><span>${dashboardGlyph('shield')}</span><h3>Vlasnik odluke</h3><p>PR priprema sadržaj; sistem i stručna služba potvrđuju granice objave kada je to potrebno.</p><button class="table-button" data-portal-screen="approvals">Otvori odobravanja</button></aside></section>`};
portalTemplates.medical=()=>`${portalHeader('MEDICINSKA SLUŽBA','Zaštićeni medicinski radni red','<button class="ghost-button" data-action="medical-audit">Pristupni audit</button><button class="primary-button compact" data-action="refresh-medical-worklist">Osveži listu</button>')}<section class="medical-command-hero"><span class="medical-command-icon">${dashboardGlyph('medical')}</span><div><span class="eyebrow">AKTIVNA SMENA · DOM OMLADINE</span><h2>Jasan red za tim, bez portala u kartonu.</h2><p>Radni red povezuje termin i potvrđen prijem. Klinička odluka, beleške i ishod ostaju isključivo u medicinskom sistemu.</p></div><button class="table-button" data-action="medical-access-policy">Pravila pristupa</button></section><section class="medical-command-grid">${[['Čeka pregled',medicalVisits.filter(item=>item.status==='Čeka pregled').length,'primljeni na prijemu','wine','prioritet','queue'],['U pregledu',medicalVisits.filter(item=>item.status==='U pregledu').length,'aktivan lekar','aqua','uživo','medical'],['Evidentiran ishod',medicalVisits.filter(item=>item.status==='Ishod evidentiran').length,'danas','mint','završeno','shield'],['Audit pristupa','100%','sintetički demo zapis','amber','kontrolisano','chart']].map(item=>`<button class="premium-metric ${item[3]}" ${item[0]==='Audit pristupa'?'data-action="medical-audit"':'data-action="refresh-medical-worklist"'}><span class="metric-visual">${dashboardGlyph(item[5])}</span><span><small>${item[0]}</small><strong>${item[1]}</strong><em>${item[2]}</em></span><b>${item[4]}</b></button>`).join('')}</section><section class="medical-workspace"><section class="premium-panel medical-queue-panel"><div class="premium-panel-head"><div><span class="eyebrow">AKTIVNA SMENA</span><h2>Današnji medicinski red</h2><p>Dom omladine · 10:00–14:00 · 3 osobe u zaštićenom toku</p></div><button class="table-button" data-action="medical-audit">Pristupni audit</button></div><div class="medical-worklist premium-worklist">${medicalVisits.map((visit,index)=>`<article class="medical-visit-card premium-visit ${visit.tone}" data-action="open-medical-visit" data-visit="${visit.id}"><div class="visit-order">${String(index+1).padStart(2,'0')}</div><span class="staff-avatar">${visit.initials}</span><div><strong>${visit.name}</strong><small>${visit.reference} · termin ${visit.time} · prijem ${visit.checkIn}</small><p>${visit.history}</p></div><div>${pill(visit.status,visit.tone)}<button class="table-button" data-action="open-medical-visit" data-visit="${visit.id}">Otvori karton</button></div></article>`).join('')}</div></section><aside class="medical-side-rail"><section class="side-brief"><span class="eyebrow">DEŽURSTVO</span><h3>Dr Ivan Marković</h3><p>Aktivni lekar · Dom omladine</p><div><span>3</span><small>osobe u radnom redu</small></div><button class="table-button" data-action="medical-audit">Audit pristupa</button></section><section class="side-checklist"><span class="eyebrow">SIGURAN TOK</span><div><b>01</b><p>Prijem je potvrdio dolazak</p></div><div><b>02</b><p>Medicinski tim otvara zaštićeni karton</p></div><div><b>03</b><p>Ishod ne dolazi u portal bez odobrenog izvora</p></div></section></aside></section>`;

const premiumMapDashboardTemplate=portalTemplates.dashboard;
portalTemplates.dashboard=()=>premiumMapDashboardTemplate().replace(/<div class="portal-map-visual">[\s\S]*?<\/section><section class="premium-panel priority-panel">/,'<div class="portal-map-toolbar"><span><i></i> Otvorena ulična karta · OpenStreetMap</span><button class="table-button" data-action="center-portal-map">Centriraj</button></div><div id="portal-dashboard-street-map" class="portal-street-map" aria-label="Interaktivna karta ustanova i akcija"></div><div class="map-context-card"><span class="live-status"><i></i> Aktivan punkt</span><strong>Dom omladine · Prijem 1</strong><small>40 mesta · 2 medicinska tima · 6 aktivnih poseta</small></div></section><section class="premium-panel priority-panel">');
function premiumDayFlow(){const counts=intakeCounts();const inProgress=counts.checkedIn+counts.medical;return `<section class="daily-journey"><header class="daily-journey-head"><div><span class="eyebrow">OPERATIVNA PUTANJA · 12. OKTOBAR</span><h2>Tok dana</h2><p>Jasan redosled odgovornosti od potvrđene pripreme do zatvaranja akcije.</p></div><div class="journey-live-status"><i></i><span><strong>Akcija u toku</strong><small>${inProgress} osoba u aktivnom procesu</small></span></div><button class="table-button" data-portal-screen="reports">Dnevni izveštaj</button></header><div class="journey-progress" aria-label="Napredak današnje akcije"><span style="width:48%"></span></div><div class="journey-steps"><article class="is-complete"><div class="journey-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></svg></div><div><span>01 · ZAVRŠENO</span><h3>Priprema akcije</h3><p>Smene, kapacitet i javna objava potvrđeni.</p></div><button data-portal-screen="events" aria-label="Otvori akcije"><span>↗</span></button></article><article class="is-active"><div class="journey-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 5h16v14H4z"/><path d="M8 9h8M8 13h5"/></svg></div><div><span>02 · AKTIVNO SADA</span><h3>Prijem i red čekanja</h3><p>${counts.scheduled} čeka prijem · ${counts.checkedIn} prijavljena.</p></div><button data-portal-screen="operations" aria-label="Otvori tok prijema"><span>↗</span></button></article><article><div class="journey-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 4v16M4 12h16"/><circle cx="12" cy="12" r="8"/></svg></div><div><span>03 · SLEDEĆI KORAK</span><h3>Medicinski radni tok</h3><p>${counts.medical} osobe predate timu kroz zaštićen tok.</p></div><button data-portal-screen="medical" aria-label="Otvori medicinski radni tok"><span>↗</span></button></article><article><div class="journey-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 3h14v18H5z"/><path d="M8 8h8M8 12h8M8 16h5"/></svg></div><div><span>04 · PLANIRANO</span><h3>Zatvaranje i izveštaj</h3><p>Zbirni rezultat, vlasnik odluke i audit trag.</p></div><button data-portal-screen="reports" aria-label="Otvori izveštaje"><span>↗</span></button></article></div></section>`}
const premiumTimelineDashboardTemplate=portalTemplates.dashboard;
portalTemplates.dashboard=()=>premiumTimelineDashboardTemplate().replace(/<section class="activity-rail">[\s\S]*?<\/section>$/,premiumDayFlow());
function dashboardGlyph(type){const glyphs={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M8 3v4M16 3v4M3 10h18M8 14h3M8 17h5"/>',queue:'<circle cx="9" cy="8" r="3"/><path d="M3 20a6 6 0 0 1 12 0M17 8h4M17 12h4M17 16h3"/>',medical:'<circle cx="12" cy="12" r="8"/><path d="M12 8v8M8 12h8"/>',chart:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',pin:'<path d="M20 10c0 5.4-8 11-8 11S4 15.4 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',shield:'<path d="M12 3 4 6v6c0 5 3.4 8 8 9 4.6-1 8-4 8-9V6Z"/><path d="m9 12 2 2 4-4"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${glyphs[type]||glyphs.chart}</svg>`}
function premiumSuperAdminDashboard(){const counts=intakeCounts();const inProgress=counts.checkedIn+counts.medical;const capacity=Math.round((inProgress/adminIntakeRows.length)*100);return `<section class="dashboard-command-hero"><div class="dashboard-hero-copy"><div class="dashboard-hero-topline"><span class="eyebrow">OPERATIVNI CENTAR · 12. OKTOBAR</span><span class="dashboard-date-chip">Ponedeljak · 10:42</span></div><h1>Današnja akcija,<br><em>pod punom kontrolom.</em></h1><p>Dom omladine · Beograd · Prijem 1. Operativa, kapacitet i odgovornosti su objedinjeni, dok medicinski podaci ostaju u zaštićenom toku.</p><div class="dashboard-hero-actions"><button class="primary-button" data-portal-screen="operations">Otvori tok prijema</button><button class="ghost-button" data-portal-screen="command">Komandni centar</button></div></div><aside class="dashboard-live-card"><div class="dashboard-live-head"><span class="live-status"><i></i> Akcija u toku</span><button class="dashboard-icon-button" data-action="open-facility" aria-label="Otvori detalj akcije">↗</button></div><div class="dashboard-live-location"><span class="dashboard-live-icon">${dashboardGlyph('pin')}</span><div><strong>Dom omladine</strong><small>10:00–14:00 · Prijem 1</small></div></div><div class="dashboard-capacity"><div class="dashboard-capacity-ring" style="--capacity:${capacity}%"><strong>${capacity}%</strong><small>aktivnog toka</small></div><div><span>Raspoloživi kapacitet</span><strong>${adminIntakeRows.length-inProgress} termina</strong><small>sledeća provera u 11:00</small></div></div><div class="dashboard-live-footer"><span><b>${counts.scheduled}</b> čeka prijem</span><span><b>${counts.medical}</b> kod tima</span></div></aside></section><section class="dashboard-kpi-grid"><button class="dashboard-kpi wine" data-portal-screen="operations"><span class="dashboard-kpi-icon">${dashboardGlyph('calendar')}</span><span class="dashboard-kpi-copy"><small>REZERVISANO</small><strong>${counts.scheduled}</strong><em>čeka prijem</em></span><b>Danas</b></button><button class="dashboard-kpi aqua" data-portal-screen="operations"><span class="dashboard-kpi-icon">${dashboardGlyph('queue')}</span><span class="dashboard-kpi-copy"><small>PRIJAVLJENO</small><strong>${counts.checkedIn}</strong><em>u redu za tim</em></span><b>Uživo</b></button><button class="dashboard-kpi mint" data-portal-screen="medical"><span class="dashboard-kpi-icon">${dashboardGlyph('medical')}</span><span class="dashboard-kpi-copy"><small>MEDICINSKI TOK</small><strong>${counts.medical}</strong><em>logistički predato</em></span><b>Aktivno</b></button><button class="dashboard-kpi amber" data-portal-screen="events"><span class="dashboard-kpi-icon">${dashboardGlyph('chart')}</span><span class="dashboard-kpi-copy"><small>POPUNJENOST</small><strong>${capacity}%</strong><em>${adminIntakeRows.length} termina danas</em></span><b>Kapacitet</b></button></section><section class="dashboard-decision-grid">${dashboardSignals.map((signal,index)=>`<article class="dashboard-decision ${signal.tone}"><span class="dashboard-decision-index">0${index+1}</span><div><small>${signal.label.toUpperCase()}</small><h2>${signal.title}</h2><p>${signal.text}</p></div><button class="table-button" data-portal-screen="${signal.screen}">${signal.button} <b>→</b></button></article>`).join('')}</section><section class="dashboard-workbench"><section class="dashboard-network-panel"><header><div><span class="eyebrow">MREŽA AKCIJA</span><h2>Lokacije i aktivni kapaciteti</h2><p>Operativni prikaz demonstracionih akcija širom Srbije.</p></div><div class="network-actions"><button class="table-button" data-action="center-portal-map">Cela Srbija</button><button class="primary-button compact" data-action="open-location-map">Otvori mapu</button></div></header><div id="portal-dashboard-street-map" class="portal-street-map dashboard-street-map" aria-label="Interaktivna karta ustanova i akcija"></div><footer class="dashboard-map-footer"><span><i></i> Aktivna lokacija</span><strong>Dom omladine · 6 osoba u toku</strong><button data-action="open-facility">Detalj akcije →</button></footer></section><aside class="dashboard-priority-panel"><header><div><span class="eyebrow">RADNI PRIORITETI</span><h2>Odluke koje ne čekaju</h2></div><button class="table-button" data-portal-screen="command">Svi zadaci</button></header><div class="dashboard-priority-list">${portalAlerts.slice(0,3).map((alert,index)=>`<button class="dashboard-priority-row ${alert.tone}" data-action="open-alert" data-alert="${alert.id}"><span>${String(index+1).padStart(2,'0')}</span><div><strong>${alert.title}</strong><small>${alert.detail}</small></div><b>→</b></button>`).join('')}</div><footer><span>${dashboardGlyph('shield')}</span><p><strong>Kontrolisana odgovornost</strong>Svaka odluka ima vlasnika i audit trag.</p></footer></aside></section>${premiumDayFlow()}`}
