function workIcon(type){const paths={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M8 3v4M16 3v4M3 10h18M8 14h3M8 17h5"/>',queue:'<circle cx="9" cy="8" r="3"/><path d="M3 20a6 6 0 0 1 12 0M17 8h4M17 12h4M17 16h3"/>',medical:'<circle cx="12" cy="12" r="8"/><path d="M12 8v8M8 12h8"/>',report:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',pin:'<path d="M20 10c0 5.4-8 11-8 11S4 15.4 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',shield:'<path d="M12 3 4 6v6c0 5 3.4 8 8 9 4.6-1 8-4 8-9V6Z"/><path d="m9 12 2 2 4-4"/>',message:'<path d="M4 5h16v11H7l-3 3Z"/><path d="M8 9h8M8 12h5"/>',campaign:'<path d="m3 11 15-6v14L3 13Z"/><path d="M18 9a3 3 0 0 1 0 6M7 14l1 6h4l-2-7"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20a6 6 0 0 1 12 0M16 5a3 3 0 0 1 0 6M17 14a5 5 0 0 1 4 5"/>',key:'<circle cx="8" cy="15" r="3"/><path d="m10 13 9-9M15 4h4v4M13 10l2 2"/>',network:'<circle cx="12" cy="5" r="2"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/><path d="M12 7v5M6 16v-2h12v2"/>',code:'<path d="m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h13M13 7l5 5-5 5"/>'};return `<svg class="work-icon" viewBox="0 0 24 24" aria-hidden="true">${paths[type]||paths.report}</svg>`}
function currentAction(){return workspaceActions.find(item=>item.id===state.sharedAction)||workspaceActions[0]}
function contextPicker(target){return `<section class="context-picker"><header><span class="eyebrow">RADNI KONTEKST</span><h3>Izaberite akciju</h3><p>Aktivne, planirane i završene akcije imaju odvojene radne redove i istoriju.</p></header>${['U toku','Planirano','Završeno'].map(status=>`<div class="context-group"><span>${status}</span>${workspaceActions.filter(item=>item.state===status).map(item=>`<button data-action="select-shared-action" data-action-id="${item.id}" data-target-screen="${target}"><span>${workIcon(status==='U toku'?'queue':status==='Planirano'?'calendar':'report')}</span><div><strong>${item.name}</strong><small>${item.city} · ${new Date(`${item.date}T12:00`).toLocaleDateString('sr-Latn-RS',{day:'numeric',month:'long',year:'numeric'})} · ${item.time}</small></div>${pill(item.state,item.tone)}<b>${workIcon('arrow')}</b></button>`).join('')}</div>`).join('')}</section>`}
function actionScope(action=currentAction()){return `<button class="action-scope" data-action="open-shared-action-picker" data-target-screen="${state.portalScreen}"><span>${workIcon('calendar')}</span><span><small>IZABRANA AKCIJA</small><strong>${action.name} · ${action.city}</strong></span><em>${action.state}</em>${workIcon('arrow')}</button>`}
const actionArchives={
  skc:{reception:[['Jovana Đorđević','JĐ','KZ-SKC-6101','09:30','Zakazan'],['Marko Arsić','MA','KZ-SKC-6102','09:45','Zakazan'],['Teodora Ilić','TI','KZ-SKC-6103','10:00','Zakazan']],medical:[]},
  nis:{reception:[['Luka Stojanović','LS','KZ-NI-7721','10:15','Zakazan'],['Sofija Nikolić','SN','KZ-NI-7722','10:30','Zakazan']],medical:[]},
  dunav:{reception:[['Ana Kovačević','AK','KZ-DU-4106','09:40','Ishod evidentiran'],['Nemanja Savić','NS','KZ-DU-4107','10:00','Ishod evidentiran'],['Mina Radović','MR','KZ-DU-4108','10:20','Nije došao']],medical:[{id:'archive-du-1',initials:'AK',name:'Ana Kovačević',reference:'KZ-DU-4106',time:'09:40',checkIn:'09:37',status:'Ishod evidentiran',tone:'mint',history:'Zatvoren sintetički zapis · 22. avgust 2026.'},{id:'archive-du-2',initials:'NS',name:'Nemanja Savić',reference:'KZ-DU-4107',time:'10:00',checkIn:'09:56',status:'Ishod evidentiran',tone:'mint',history:'Zatvoren sintetički zapis · 22. avgust 2026.'}]},
  kragujevac:{reception:[['Vanja Petrović','VP','KZ-KG-2301','10:00','Ishod evidentiran'],['Ognjen Simić','OS','KZ-KG-2302','10:20','Ishod evidentiran']],medical:[{id:'archive-kg-1',initials:'VP',name:'Vanja Petrović',reference:'KZ-KG-2301',time:'10:00',checkIn:'09:55',status:'Ishod evidentiran',tone:'mint',history:'Zatvoren sintetički zapis · 16. jun 2025.'}]}
};
function actionRows(action=currentAction(),kind='reception'){if(action.id==='dom-omladine')return kind==='medical'?medicalVisits:adminIntakeRows;return actionArchives[action.id]?.[kind]||[]}
function monthMeta(){return new Date(state.calendarYear,state.calendarMonth,1)}
function monthEvents(){const prefix=`${state.calendarYear}-${String(state.calendarMonth+1).padStart(2,'0')}`;return scheduledCalendarEvents.filter(item=>item.date.startsWith(prefix))}
function calendarGrid(){const date=monthMeta(),offset=(date.getDay()+6)%7,days=new Date(state.calendarYear,state.calendarMonth+1,0).getDate(),monthLabel=date.toLocaleDateString('sr-Latn-RS',{month:'long',year:'numeric'});const cells=[...Array(offset).fill(null),...Array.from({length:days},(_,i)=>i+1)];return `<section class="scheduler-shell"><header><div><span class="eyebrow">RASPORED AKCIJA</span><h2>${monthLabel[0].toUpperCase()+monthLabel.slice(1)}</h2><p>Izaberite mesec, godinu ili dan. Lista prikazuje zakazane, završene i buduće akcije.</p></div><div class="scheduler-controls"><button data-action="calendar-shift" data-step="-1" aria-label="Prethodni mesec">${workIcon('arrow')}</button><select data-action="calendar-month">${['januar','februar','mart','april','maj','jun','jul','avgust','septembar','oktobar','novembar','decembar'].map((name,index)=>`<option value="${index}" ${state.calendarMonth===index?'selected':''}>${name[0].toUpperCase()+name.slice(1)}</option>`).join('')}</select><select data-action="calendar-year">${[2025,2026,2027].map(year=>`<option value="${year}" ${state.calendarYear===year?'selected':''}>${year}</option>`).join('')}</select><button data-action="calendar-shift" data-step="1" aria-label="Sledeći mesec">${workIcon('arrow')}</button></div></header><div class="calendar-weekdays">${['PON','UTO','SRE','ČET','PET','SUB','NED'].map(day=>`<span>${day}</span>`).join('')}</div><div class="scheduler-days">${cells.map(day=>{if(!day)return '<span class="scheduler-empty"></span>';const key=`${state.calendarYear}-${String(state.calendarMonth+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,events=scheduledCalendarEvents.filter(item=>item.date===key),selected=state.selectedCalendarDate===key;return `<button class="scheduler-day ${events.length?'has-event':''} ${selected?'selected':''}" data-action="calendar-date" data-date="${key}"><strong>${day}</strong>${events.length?`<small>${events.length} akcija</small><i></i>`:'<small>—</small>'}</button>`}).join('')}</div></section>`}
function scheduleList(){const rows=monthEvents().filter(item=>!state.selectedCalendarDate||item.date===state.selectedCalendarDate);return `<section class="premium-panel schedule-list"><header class="premium-panel-head"><div><span class="eyebrow">${state.selectedCalendarDate?'IZABRANI DATUM':'MESEČNI PREGLED'}</span><h2>${rows.length?`${rows.length} akcija u rasporedu`:'Nema akcija za izabrani datum'}</h2></div><button class="table-button" data-action="calendar-all">Prikaži ceo mesec</button></header><div class="schedule-rows">${rows.map(item=>`<button data-action="open-scheduled-event" data-event-id="${item.id}"><span class="schedule-date"><strong>${new Date(`${item.date}T12:00`).getDate()}</strong><small>${new Date(`${item.date}T12:00`).toLocaleDateString('sr-Latn-RS',{month:'short'}).replace('.','')}</small></span><span><strong>${item.name}</strong><small>${item.city} · ${item.time} · ${item.capacity} mesta</small></span>${pill(item.state,item.tone)}<b>${workIcon('arrow')}</b></button>`).join('')||'<div class="empty-workspace"><span>'+workIcon('calendar')+'</span><h3>Ovaj dan je slobodan.</h3><p>Promenite datum ili prikažite ceo mesec.</p></div>'}</div></section>`}
function renderWorkspaceHeader(kicker,title,action){return `${portalHeader(kicker,title,`<button class="ghost-button" data-action="open-shared-action-picker" data-target-screen="${state.portalScreen}">${workIcon('calendar')} Izaberi akciju</button>${action||''}`)}${actionScope()}`}
function routeCard(icon,kicker,title,copy,target,label='Otvori'){return `<article class="route-card"><span class="route-card-icon">${workIcon(icon)}</span><div><small>${kicker}</small><h3>${title}</h3><p>${copy}</p></div><button class="table-button" ${target.startsWith('#')?`data-action="open-demo-route" data-route="${target.slice(1)}"`:`data-portal-screen="${target}"`}>${label}</button></article>`}

decoratePortalActions=()=>{$$('#portal-screen button[data-action], #portal-screen button[data-portal-screen]').forEach(button=>{if(button.querySelector('.work-icon')||button.matches('.scheduler-day,.checkin-row,.schedule-rows button,.context-picker button'))return;const label=(button.textContent||'').trim();if(!label||button.classList.contains('table-button')&&button.querySelector('.button-arrow'))return;const key=button.dataset.portalScreen||button.dataset.action||'';const map={events:'calendar',operations:'queue',medical:'medical',reports:'report',campaigns:'campaigns',donors:'users',content:'message',communications:'message','qr-access':'key',hierarchy:'network',integrations:'code',governance:'shield',staff:'users',checkin:'queue',approvals:'check',command:'report'};button.classList.add('has-svg-icon');button.insertAdjacentHTML('afterbegin',workIcon(map[key]||'arrow'))});};
portalTemplates.events=()=>`${portalHeader('AKCIJE I TERMINI','Raspored, meseci i istorija','<button class="ghost-button" data-action="calendar-today">Tekući mesec</button><button class="primary-button compact" data-action="create-event">+ Nova akcija</button>')}${calendarGrid()}${scheduleList()}`;
portalTemplates.checkin=()=>{const action=currentAction(),rows=actionRows(action);return `${renderWorkspaceHeader('PRIJEM DAVALACA','Prijem, akcije i istorija','<button class="primary-button compact" data-action="open-reception-app">Otvori prijem</button>')}<section class="workspace-hero"><div><span class="eyebrow">${action.state.toUpperCase()} · ${action.time}</span><h2>${action.state==='U toku'?'Zakazani dolasci za aktivnu smenu':action.state==='Planirano'?'Priprema prijema za planiranu akciju':'Istorija prijema završene akcije'}</h2><p>${action.scope}. Prijem radi samo sa identitetom, rezervacijom i statusom dolaska.</p></div><span class="workspace-stat"><strong>${action.state==='U toku'?rows.length:'—'}</strong><small>${action.state==='U toku'?'termina u listi':'nema aktivnog prijema'}</small></span></section><section class="workspace-columns"><section class="premium-panel"><header class="premium-panel-head"><div><span class="eyebrow">${action.state==='Završeno'?'ARHIVA PRIJEMA':'RADNI RED'}</span><h2>${action.name}</h2></div><button class="table-button" data-portal-screen="operations">Operativni tok</button></header><div class="checkin-list">${rows.length?rows.map((row,index)=>{const record=Array.isArray(row)?{name:row[0],initials:row[1],ref:row[2],time:row[3],status:row[4],tone:statusTone(row[4])}:{name:row.name,initials:row.initials,ref:row.reference,time:row.time,status:row.status,tone:row.tone};return `<button class="checkin-row" data-action="open-intake-record" data-reservation="${record.ref}"><span class="checkin-order">${String(index+1).padStart(2,'0')}</span><span class="staff-avatar">${record.initials}</span><span><strong>${record.name}</strong><small>${record.ref} · termin ${record.time}</small></span>${pill(record.status,record.tone)}<b>${workIcon('arrow')}</b></button>`}).join(''):`<div class="empty-workspace"><span>${workIcon(action.state==='Planirano'?'calendar':'report')}</span><h3>${action.state==='Planirano'?'Smena još nije otvorena.':'Radni red je zatvoren.'}</h3><p>${action.state==='Planirano'?'Rezervacije i osoblje se prikazuju kada koordinator otvori akciju.':'Otvorite zbirni izveštaj i audit akcije.'}</p><button class="primary-button compact" data-portal-screen="reports">Otvori izveštaj</button></div>`}</div></section><aside class="workspace-side">${routeCard('queue','TOK PRIJEMA','Skeniranje i ručna pretraga','QR ili broj rezervacije vode do jedne tačne evidencije.','operations','Otvori tok')}${routeCard('shield','GRANICA PRISTUPA','Samo dodeljena smena','Zdravstveni sadržaj nikada nije deo prijemnog radnog prostora.','access','Pravila')}</aside></section>`};
portalTemplates.operations=()=>{const action=currentAction(),live=action.state==='U toku',rows=live?filteredIntakeRows():[],counts=intakeCounts();return `${renderWorkspaceHeader('OPERATIVNI TOK',`${action.name} · ${action.state.toLowerCase()}`,`<button class="primary-button compact" data-action="refresh-operations">Osveži tok</button>`)}<section class="workspace-hero"><div><span class="eyebrow">${action.city.toUpperCase()} · ${action.time}</span><h2>${live?'Jedna osoba, jedan sledeći korak.':action.state==='Planirano'?'Planirana akcija, bez aktivnog reda.':'Završena akcija, sa zatvorenom istorijom.'}</h2><p>${action.scope}. Status se ne menja duplim komandama i svaki prelaz ostavlja audit trag.</p></div><span class="workspace-stat"><strong>${live?counts.checkedIn+counts.medical:'—'}</strong><small>${live?'u aktivnom toku':'radni tok nije otvoren'}</small></span></section><section class="flow-status-grid">${[['Zakazano',counts.scheduled,'Zakazan','calendar'],['Prijavljeno',counts.checkedIn,'Prijavljen','queue'],['Kod tima',counts.medical,'Kod tima','medical'],['Nisu došli',counts.noShow,'Nije došao','report']].map((item,index)=>`<button class="flow-status ${['scheduled','checked','medical','no-show'][index]}" ${live?`data-portal-filter="operations-status" data-status="${item[2]}"`:'data-action="open-shared-action-picker" data-target-screen="operations"'}><span>${workIcon(item[3])}</span><div><small>${item[0]}</small><strong>${live?item[1]:'—'}</strong><p>${live?'Otvori povezanu listu':'Izaberi aktivnu akciju'}</p></div>${workIcon('arrow')}</button>`).join('')}</section><section class="premium-panel workflow-list"><header class="premium-panel-head"><div><span class="eyebrow">${live?'DANAŠNJI TERMINI':'KONTEKST AKCIJE'}</span><h2>${live?'Lista je povezana sa statusima iznad':'Istorija i sledeće radnje'}</h2></div><button class="table-button" data-portal-screen="checkin">Prijem davalaca</button></header>${live?`<div class="operations-toolbar"><div class="toolbar-search"><span>${workIcon('users')}</span><input class="search-input" data-portal-filter="operations-query" value="${state.operationsQuery}" placeholder="Pretraži ime ili broj rezervacije"></div><select class="select-control" data-portal-filter="operations-status"><option value="all">Svi statusi</option><option value="Zakazan">Zakazano</option><option value="Prijavljen">Prijavljeni</option><option value="Kod tima">Kod medicinskog tima</option><option value="Nije došao">Nisu došli</option></select></div><table class="data-table operations-table"><thead><tr><th>Davalac i rezervacija</th><th>Termin</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(intakeRow).join('')}</tbody></table>`:`<div class="empty-workspace"><span>${workIcon(action.state==='Planirano'?'calendar':'report')}</span><h3>${action.state==='Planirano'?'Akcija čeka otvaranje prijema.':'Rezultat akcije je zaključen.'}</h3><p>${action.state==='Planirano'?'Smena, rezervacije i kapacitet se prikazuju kada akcija postane aktivna.':'Dostupni su zbirni izveštaj, audit i istorija bez zdravstvenog sadržaja.'}</p><button class="primary-button compact" data-portal-screen="reports">Otvori zbirni izveštaj</button></div>`}</section>`};
portalTemplates.medical=()=>{const action=currentAction(),live=action.state==='U toku',visits=actionRows(action,'medical');return `${renderWorkspaceHeader('MEDICINSKA SLUŽBA','Zaštićeni radni red po akciji',`<button class="primary-button compact" data-action="medical-audit">Pristupni audit</button>`)}<section class="medical-workspace-hero"><span>${workIcon('medical')}</span><div><span class="eyebrow">${action.name.toUpperCase()} · ${action.state.toUpperCase()}</span><h2>${live?'Aktivna smena: klinički red bez operativne buke.':'Medicinski radni red je vezan za status akcije.'}</h2><p>Karton se otvara samo za aktivnu, dodeljenu smenu. Planirane i završene akcije imaju odvojenu pripremu odnosno arhivu.</p></div><button class="table-button" data-action="medical-access-policy">Pravila pristupa</button></section><section class="medical-command-grid">${[['Čeka pregled',live?visits.filter(x=>x.status==='Čeka pregled').length:'—','queue'],['U pregledu',live?visits.filter(x=>x.status==='U pregledu').length:'—','medical'],['Evidentiran ishod',live?visits.filter(x=>x.status==='Ishod evidentiran').length:'—','check'],['Audit pristupa','100%','shield']].map(item=>`<button class="premium-metric interactive-card" data-action="${item[0]==='Audit pristupa'?'medical-audit':'open-shared-action-picker'}" data-target-screen="medical"><span class="metric-visual">${workIcon(item[2])}</span><span><small>${item[0]}</small><strong>${item[1]}</strong><em>${live?'Aktivna smena':'Izaberi akciju'}</em></span></button>`).join('')}</section><section class="workspace-columns"><section class="premium-panel"><header class="premium-panel-head"><div><span class="eyebrow">${live?'AKTIVNA SMENA':'MEDICINSKI KONTEKST'}</span><h2>${action.name}</h2></div><button class="table-button" data-action="medical-audit">Audit</button></header><div class="medical-worklist premium-worklist">${visits.length?visits.map((visit,index)=>`<article class="medical-visit-card premium-visit ${visit.tone}" data-action="open-medical-visit" data-visit="${visit.id}"><div class="visit-order">${String(index+1).padStart(2,'0')}</div><span class="staff-avatar">${visit.initials}</span><div><strong>${visit.name}</strong><small>${visit.reference} · termin ${visit.time} · prijem ${visit.checkIn}</small><p>${visit.history}</p></div><div>${pill(visit.status,visit.tone)}<button class="table-button" data-action="open-medical-visit" data-visit="${visit.id}">Otvori karton</button></div></article>`).join(''):`<div class="empty-workspace"><span>${workIcon(action.state==='Planirano'?'calendar':'report')}</span><h3>${action.state==='Planirano'?'Medicinski red nije otvoren.':'Medicinski red je arhiviran.'}</h3><p>${action.state==='Planirano'?'Kada prijem počne, vide se samo potvrđene osobe aktivne smene.':'Nakon završetka ostaju samo odobreni zbirni i audit podaci.'}</p></div>`}</div></section><aside class="workspace-side">${routeCard('shield','ZAŠTIĆEN TOK','Granica medicinskog pristupa','Razlog, vreme i korisnik ostaju u neizmenjivom auditu.','governance','Otvori audit')}${routeCard('calendar','AKCIJA','Promeni radni kontekst','Planirani i završeni tokovi ne mešaju se sa aktivnom smenom.','#choose-action','Izaberi akciju')}</aside></section>`};
portalTemplates.campaigns=()=>`${portalHeader('CILJANI POZIVI','Kampanje, talasi i učinak','<button class="ghost-button" data-action="open-demo-route" data-route="campaign-rules">Pravila slanja</button><button class="primary-button compact" data-portal-screen="campaign-builder">+ Nova kampanja</button>')}<section class="route-grid">${routeCard('campaign','AKTIVNE KAMPANJE','3 aktivne kampanje','Pregled talasa, kapaciteta i rezervacija po kampanji.','#campaign-active','Otvori kampanje')}${routeCard('check','ODOBRAVANJE','1 čeka odluku','Publika i učestalost se ne aktiviraju bez vlasnika.','approvals','Otvori odobravanja')}${routeCard('report','UČINAK','68 rezervacija','Zbirni odziv od poruke do realizovanog termina.','reports','Otvori analitiku')}${routeCard('shield','UČESTALOST','7 dana pauze','Kontrola talasa, saglasnosti i granica poziva.','#campaign-rules','Pogledaj pravila')}</section>${panel('Radna tabla kampanja',`<div class="campaign-board">${[['Potreba za 0−','Beograd · puna krv','Aktivna','16','campaign-detail'],['Akcija Novi Sad','Južnobački okrug','Aktivna','22','campaign-detail'],['Kompanija Dunav','Samo zaposleni','Čeka odobrenje','0','campaign-builder']].map((item,index)=>`<button data-portal-screen="${item[4]}" class="campaign-row"><span>${workIcon(index===0?'campaign':index===1?'message':'check')}</span><span><strong>${item[0]}</strong><small>${item[1]} · ${item[3]} rezervacija</small></span>${pill(item[2],index===2?'warning':'success')}${workIcon('arrow')}</button>`).join('')}</div>`,'<p>Svaka kartica vodi do kampanje, publike, talasa ili odobravanja.</p>','full-span')}`;
portalTemplates.donors=()=>`${portalHeader('DAVAOCI I PROVERE','Korekcije, saglasnosti i zahtevani trag','<button class="ghost-button" data-action="open-demo-route" data-route="donor-search">Pretraga zahteva</button><button class="primary-button compact" data-action="open-demo-route" data-route="new-correction">+ Novi zahtev</button>')}<section class="route-grid">${routeCard('users','ISPRAVKE PODATAKA','3 otvorena zahteva','Zahtev se proverava uz vlasnika i audit, bez menjanja medicinskog kartona.','#donor-corrections','Otvori zahteve')}${routeCard('shield','SAGLASNOSTI','Sve evidentirano','Pregled kanala i privola bez medicinskog sadržaja.','#consents','Otvori saglasnosti')}${routeCard('check','PROVERE IDENTITETA','2 čekaju proveru','Prijem proverava dokument samo za dodeljenu akciju.','checkin','Otvori prijem')}${routeCard('report','ISTORIJA ZAHTEVA','18 zatvorenih','Zbirni pregled rokova i rešenja.','#donor-history','Otvori istoriju')}</section>${panel('Zahtevi i provere',`<div class="case-grid">${[['Izmena kontakta','KZ-4821','Čeka proveru','donor-search'],['Prigovor na evidenciju','KZ-4768','Dodeljeno koordinatoru','donor-search'],['Povlačenje saglasnosti','KZ-4650','Spremno za odluku','consents']].map((item,index)=>`<button data-action="open-demo-route" data-route="${item[3]}"><span>${workIcon(['users','shield','message'][index])}</span><div><small>ZAHTEV ${String(index+1).padStart(2,'0')}</small><strong>${item[0]}</strong><em>${item[1]} · ${item[2]}</em></div>${workIcon('arrow')}</button>`).join('')}</div>`,'<p>Svaki zahtev ima vlasnika, rok, status i audit. Medicinski podaci nisu deo ovog ekrana.</p>','full-span')}`;
portalTemplates.content=()=>`${portalHeader('PR I SADRŽAJ','Redakcijski studio','<button class="ghost-button" data-action="open-content-calendar">Kalendar objava</button><button class="primary-button compact" data-action="create-news">+ Nova vest</button>')}<section class="content-production-strip"><div class="production-icon">${workIcon('message')}</div><div><span class="eyebrow">SADRŽAJ U IZRADI</span><h2>Priprema za davanje krvi</h2><p>Ovo je javni vodič, ne automatsko popunjavanje: PR uređuje sadržaj, medicinska služba proverava tvrdnje, a odgovorna osoba odobrava objavu.</p></div><div class="production-stages"><button data-action="open-news-editor" data-news="news-prep"><b>01</b><span>Nacrt</span></button><button data-action="open-news-editor" data-news="news-prep"><b>02</b><span>Stručna provera</span></button><button data-portal-screen="approvals"><b>03</b><span>Odobrenje</span></button><button data-action="open-content-calendar"><b>04</b><span>Objava</span></button></div></section><section class="route-grid content-route-grid">${routeCard('message','UREDNIK','Vesti i vodiči','Naslov, slika, izvor, verzije i mobilni pregled.','#news-editor','Otvori urednik')}${routeCard('check','STRUČNA PROVERA','2 stavke čekaju','Medicinske tvrdnje ne idu javno bez potvrde.','approvals','Otvori red')}${routeCard('calendar','KALENDAR OBJAVA','3 zakazane objave','Kanal, vreme, publika i vlasnik objave.','#content-calendar','Otvori kalendar')}${routeCard('report','UČINAK','28 objava','Zbirni odziv i doseg bez identifikacije.','reports','Otvori analitiku')}</section>${panel('Sadržaj po statusu',`<div class="editorial-row">${portalNews.map((item,index)=>`<button data-action="open-news-editor" data-news="${item.id}"><span>${workIcon(['message','calendar','check'][index])}</span><div><small>${item.type} · ${item.status}</small><strong>${item.title}</strong><em>${item.author} · ${item.updated}</em></div>${workIcon('arrow')}</button>`).join('')}</div>`,'<p>Svaki materijal otvara urednik sa verzijama, izvorom, medijem i odobravanjem.</p>','full-span')}`;
portalTemplates.reports=()=>`${portalHeader('IZVEŠTAJI I ANALITIKA','Zbirni rezultati i jasne odluke','<button class="ghost-button" data-action="open-demo-route" data-route="report-filters">Filteri izveštaja</button><button class="primary-button compact" data-action="export-report">Preuzmi zbirni izveštaj</button>')}<section class="report-hero"><span class="eyebrow">SAMO ZBIRNI DEMONSTRACIONI PODACI</span><h2>Trendovi koji vode odluci.</h2><p>Izveštaji ne sadrže identifikacione ni zdravstvene podatke davaoca.</p></section><section class="report-grid">${[['Potvrđena davanja','+18%','report'],['Kapacitet akcija','73%','calendar'],['Od poruke do termina','17%','campaign']].map(item=>`<button class="report-summary" data-action="open-demo-route" data-route="report-${item[0].replaceAll(' ','-')}"><span>${workIcon(item[2])}</span><div><small>${item[0]}</small><strong>${item[1]}</strong><em>Otvori detaljni prikaz</em></div>${workIcon('arrow')}</button>`).join('')}</section><section class="report-layout"><section class="premium-panel"><header class="premium-panel-head"><div><span class="eyebrow">DAVANJA · 6 MESECI</span><h2>Potvrđena davanja</h2></div><button class="table-button" data-action="open-demo-route" data-route="donation-trend">Detalji</button></header><div class="spark-bars symmetric-bars">${[34,48,55,44,61,76].map((value,index)=>`<i style="height:${value}%"><small>${['APR','MAJ','JUN','JUL','AVG','SEP'][index]}</small></i>`).join('')}</div></section><section class="premium-panel"><header class="premium-panel-head"><div><span class="eyebrow">KAPACITET AKCIJA</span><h2>Popunjenost po punktu</h2></div><button class="table-button" data-portal-screen="events">Otvori raspored</button></header><div class="capacity-list">${[['Dom omladine',80],['SKC',62],['Zemun',46]].map(item=>`<button data-portal-screen="events"><span>${item[0]}</span><i><b style="width:${item[1]}%"></b></i><strong>${item[1]}%</strong></button>`).join('')}</div></section><section class="premium-panel funnel-panel"><header class="premium-panel-head"><div><span class="eyebrow">KAMPANJE</span><h2>Od poruke do termina</h2></div><button class="table-button" data-portal-screen="campaigns">Kampanje</button></header><div class="symmetric-funnel">${[['Dostavljeno','1.240'],['Otvoreno','746'],['Zakazano','214'],['Realizovano','168']].map((item,index)=>`<button data-portal-screen="campaigns"><span>${String(index+1).padStart(2,'0')}</span><strong>${item[1]}</strong><small>${item[0]}</small>${workIcon('arrow')}</button>`).join('')}</div></section></section>`;
portalTemplates['qr-access']=()=>`${portalHeader('POZIVNICE I QR PRISTUP','Kontrolisan pristup osoblja','<button class="ghost-button" data-portal-screen="staff">Osoblje i pozicije</button><button class="primary-button compact" data-action="create-staff-invite">+ Nova pozivnica</button>')}<section class="access-hero"><span>${workIcon('key')}</span><div><span class="eyebrow">SUPER ADMIN · PRISTUP OSOBLJA</span><h2>Pozivnica je kontrolisan tok, ne zajednički nalog.</h2><p>Pre aktivacije se dodeljuju pozicija, ustanova, akcija, rok i MFA. QR kod samo otvara sledeći provereni korak.</p></div><button class="table-button" data-action="open-super-admin">Pravila Super admina</button></section><section class="route-grid">${routeCard('key','AKTIVNA POZIVNICA','Prijem · Dom omladine','Važi do 18:00, vezana je za jednu smenu i jednu osobu.','#invite-detail','Otvori pozivnicu')}${routeCard('users','DODELA ULOGE','6 aktivnih naloga','Pozicija, odgovornost i dodeljena akcija.','staff','Otvori osoblje')}${routeCard('shield','MFA I UREĐAJ','1 čeka potvrdu','Uređaj i MFA se potvrđuju pre otvaranja smene.','#mfa-devices','Otvori kontrole')}${routeCard('report','AUDIT PRISTUPA','18 zapisa danas','Svaka promena prava ima vlasnika i razlog.','governance','Otvori audit')}</section>${panel('Koraci aktivacije',`<div class="activation-steps">${[['01','Pozicija i odgovornost','Super admin određuje minimalan obim.'],['02','Pozivnica i identitet','Službeni kontakt potvrđuje poziv.'],['03','MFA i uređaj','Aktivira se samo odobren uređaj.'],['04','Dodeljena smena','Otvara se samo pripadajući radni prostor.']].map(item=>`<button data-action="open-demo-route" data-route="activation-${item[0]}"><span>${item[0]}</span><div><strong>${item[1]}</strong><small>${item[2]}</small></div>${workIcon('arrow')}</button>`).join('')}</div>`,'<p>Svi koraci su vidljivi, klikabilni i odvojeni da bi odgovornost bila jasna.</p>','full-span')}`;
portalTemplates.hierarchy=()=>`${portalHeader('SISTEMSKA HIJERARHIJA','Odgovornosti, delegacije i granice','<button class="ghost-button" data-portal-screen="access">Matrica prava</button><button class="primary-button compact" data-action="create-staff-invite">Dodeli poziciju</button>')}<section class="hierarchy-command"><span>${workIcon('network')}</span><div><span class="eyebrow">KONTROLISANA DELEGACIJA</span><h2>Super admin dodeljuje pristup; stručna odluka ostaje kod stručne službe.</h2><p>Svaka pozicija ima svoj radni prostor, rok, ustanovu, akciju i audit granicu.</p></div><button class="table-button" data-action="open-super-admin">Pravila</button></section><section class="hierarchy-root-premium"><span>${workIcon('shield')}</span><div><small>SUPER ADMIN ZAVODA</small><strong>Sistemi, ustanove, pozicije, delegacije, MFA i audit</strong><em>Ne preuzima kliničku odluku niti uređuje javni sadržaj umesto odgovorne uloge.</em></div><button class="primary-button compact" data-portal-screen="access">Upravljaj ovlašćenjima</button></section><section class="hierarchy-role-grid">${[['admin','Administrator','Konfiguracija, nalozi i bezbednosni događaji.','code'],['coordinator','Koordinator akcija','Akcije, kapacitet, smene i logistički tok.','calendar'],['medical','Medicinski rukovodilac','Zaštićeni klinički tok i stručna provera.','medical'],['content','PR i sadržaj','Vesti, mediji i kampanje uz odobrenje.','message'],['reception','Prijem','Rezervacija, identitet i dolazak po smeni.','queue'],['auditor','Revizor','Audit, izveštaji i nadzor bez izmene.','report']].map(item=>`<button data-action="open-role-workspace" data-role="${item[0]}"><span>${workIcon(item[3])}</span><div><small>ODGOVORNOST</small><strong>${item[1]}</strong><em>${item[2]}</em></div>${workIcon('arrow')}</button>`).join('')}</section>`;
portalTemplates.integrations=()=>`${portalHeader('IT ODRŽAVANJE I INTEGRACIJE','Sistemi, aplikacije, incidenti i oporavak','<button class="ghost-button" data-action="open-system-health">Status sistema</button><button class="primary-button compact" data-action="report-incident">+ Prijavi incident</button>')}<section class="it-hero"><span>${workIcon('code')}</span><div><span class="eyebrow">OPERATIVNI NADOR · DEMONSTRACIONO OKRUŽENJE</span><h2>Jedno mesto za veze, greške, izdavanja i oporavak.</h2><p>Ovde se upravlja tehničkim zdravljem portala i obe aplikacije. Produkcione ključeve, stvarne pacijente i medicinske podatke ovaj demo ne sadrži.</p></div><button class="table-button" data-action="show-api-boundaries">Granice pristupa</button></section><section class="it-service-grid">${[['Portal Zavoda','Dostupan','Web, rute, audit i kontrolni centar','report','it-portal'],['Kapi Života','Dostupan','Korisnička aplikacija, rezervacije i obaveštenja','users','it-donor'],['Kapi Života — Prijem','Dostupan','Skeniranje, rad smene i operativni status','queue','it-reception'],['API ugovor','Čeka povezivanje Zavoda','Verzije, autentifikacija i kontrola grešaka','code','it-api'],['Monitoring','Pripremljen','Dostupnost, greške, performanse i obaveštenja','shield','it-monitor'],['Izdavanja','Kontrolisano','Verzija, povratak izdanja i evidencija promene','calendar','it-release']].map(item=>`<button data-action="open-demo-route" data-route="${item[4]}"><span>${workIcon(item[3])}</span><div><small>${item[1]}</small><strong>${item[0]}</strong><em>${item[2]}</em></div>${workIcon('arrow')}</button>`).join('')}</section><section class="it-operations-grid"><section class="premium-panel"><header class="premium-panel-head"><div><span class="eyebrow">API I VEZE</span><h2>Kontrola integracija</h2></div><button class="table-button" data-action="check-api-health">Proveri vezu</button></header><div class="it-checklist">${[['Zdravlje servisa','/health','it-api-health'],['Operativni tok','/v1/portal/operations','it-operations'],['Dnevnik grešaka','incidenti i zahtevi','it-errors'],['Verzije klijenata','iOS, Android i web','it-release']].map(item=>`<button data-action="open-demo-route" data-route="${item[2]}"><span>${workIcon('check')}</span><div><strong>${item[0]}</strong><small>${item[1]}</small></div>${workIcon('arrow')}</button>`).join('')}</div></section><section class="premium-panel"><header class="premium-panel-head"><div><span class="eyebrow">UPRAVLJANJE PROBLEMOM</span><h2>Od prijave do oporavka</h2></div><button class="table-button" data-action="open-incidents">Otvoreni incidenti</button></header><div class="it-checklist">${[['Prijavi i klasifikuj','Vlasnik, ozbiljnost i pogođeni sistem'],['Proveri uticaj','Portal, aplikacije, API i korisnički tok'],['Reši ili vrati verziju','Kontrolisan popravak sa auditom'],['Potvrdi oporavak','Monitor, test toka i zatvaranje incidenta']].map((item,index)=>`<button data-action="open-demo-route" data-route="incident-${index+1}"><span>${String(index+1).padStart(2,'0')}</span><div><strong>${item[0]}</strong><small>${item[1]}</small></div>${workIcon('arrow')}</button>`).join('')}</div></section></section>`;
document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(!node)return;const action=node.dataset.action;if(action==='calendar-shift'){state.calendarMonth+=Number(node.dataset.step);if(state.calendarMonth<0){state.calendarMonth=11;state.calendarYear--}if(state.calendarMonth>11){state.calendarMonth=0;state.calendarYear++}state.selectedCalendarDate=null;renderPortal('events')}if(action==='calendar-month'){state.calendarMonth=Number(node.value);state.selectedCalendarDate=null;renderPortal('events')}if(action==='calendar-year'){state.calendarYear=Number(node.value);state.selectedCalendarDate=null;renderPortal('events')}if(action==='calendar-date'){state.selectedCalendarDate=node.dataset.date;renderPortal('events')}if(action==='calendar-all'){state.selectedCalendarDate=null;renderPortal('events')}if(action==='calendar-today'){state.calendarMonth=8;state.calendarYear=2026;state.selectedCalendarDate=null;renderPortal('events')}if(action==='open-scheduled-event'){const item=scheduledCalendarEvents.find(entry=>entry.id===node.dataset.eventId);if(item)showDialog(item.name,`<div class="decision-grid"><article class="decision-card"><h3>${item.city}</h3><p>${item.date} · ${item.time}<br>Kapacitet: ${item.capacity}</p></article><article class="decision-card"><h3>Status</h3><p>${item.state}. Ovaj prikaz koristi sintetičke podatke i vodi u odgovarajući radni prostor.</p></article></div><div class="button-row"><button class="ghost-button" data-action="close-dialog">Zatvori</button><button class="primary-button" data-action="select-shared-action" data-action-id="${item.id==='skc-sep'?'skc':item.id}" data-target-screen="operations">Otvori radni kontekst</button></div>`)}if(action==='open-shared-action-picker')showDialog('Izbor akcije',contextPicker(node.dataset.targetScreen||state.portalScreen));if(action==='select-shared-action'){state.sharedAction=node.dataset.actionId;state.selectedOperation=node.dataset.actionId;dialog.close();renderPortal(node.dataset.targetScreen||'operations')}if(action==='open-demo-route'){const labels={"campaign-active":'Aktivne kampanje',"campaign-rules":'Pravila kampanja',"donor-search":'Pretraga zahteva',"new-correction":'Novi zahtev',"consents":'Saglasnosti',"news-editor":'Urednik sadržaja',"content-calendar":'Kalendar objava',"report-filters":'Filteri izveštaja',"choose-action":'Izbor akcije',"invite-detail":'Detalj pozivnice',"mfa-devices":'MFA i uređaji',"it-api":'API integracija',"it-monitor":'Monitoring sistema',"it-release":'Izdavanja aplikacija'};showDialog(labels[node.dataset.route]||'Radni prostor',`<div class="route-dialog"><span>${workIcon('shield')}</span><h3>${labels[node.dataset.route]||'Detalj radnog prostora'}</h3><p>Ovaj klikabilni demonstracioni tok je spreman za povezivanje sa odobrenim izvorom Zavoda. U produkciji bi prikazao samo podatke za koje ta uloga ima dozvolu, uz audit.</p><button class="primary-button" data-action="close-dialog">Zatvori</button></div>`)} });
document.addEventListener('change',event=>{const action=event.target.dataset.action;if(action==='calendar-month'){state.calendarMonth=Number(event.target.value);state.selectedCalendarDate=null;renderPortal('events')}if(action==='calendar-year'){state.calendarYear=Number(event.target.value);state.selectedCalendarDate=null;renderPortal('events')}});

portalTemplates.operations=()=>{const action=currentAction(),live=action.state==='U toku',rows=actionRows(action),counts=live?intakeCounts():{scheduled:rows.filter(row=>row[4]==='Zakazan').length,checkedIn:rows.filter(row=>row[4]==='Prijavljen').length,medical:rows.filter(row=>row[4]==='Kod tima'||row[4]==='Ishod evidentiran').length,noShow:rows.filter(row=>row[4]==='Nije došao').length};return `${renderWorkspaceHeader('OPERATIVNI TOK',`${action.name} · ${action.state.toLowerCase()}`,`<button class="primary-button compact" data-action="refresh-operations">${workIcon('queue')} Osveži tok</button>`)}<section class="workspace-hero"><div><span class="eyebrow">${action.city.toUpperCase()} · ${action.time}</span><h2>${live?'Jedna osoba, jedan sledeći korak.':action.state==='Planirano'?'Plan prijema je spreman pre otvaranja smene.':'Završena akcija ima jasan operativni arhiv.'}</h2><p>${action.scope}. Svaki status, plan i arhiva ostaju vezani za izabranu akciju.</p></div><span class="workspace-stat"><strong>${rows.length}</strong><small>${live?'zapisa u toku':action.state==='Planirano'?'rezervacije u pripremi':'zapisa u istoriji'}</small></span></section><section class="flow-status-grid">${[['Zakazano',counts.scheduled,'calendar'],['Prijavljeno',counts.checkedIn,'queue'],['Kod tima',counts.medical,'medical'],['Nisu došli',counts.noShow,'report']].map((item,index)=>`<button class="flow-status ${['scheduled','checked','medical','no-show'][index]}" data-action="open-demo-route" data-route="operation-${index}"><span>${workIcon(item[2])}</span><div><small>${item[0]}</small><strong>${item[1]}</strong><p>${live?'Povezana lista':'Pregled konteksta'}</p></div>${workIcon('arrow')}</button>`).join('')}</section><section class="premium-panel workflow-list"><header class="premium-panel-head"><div><span class="eyebrow">${live?'AKTIVNI RADNI RED':action.state==='Planirano'?'PRIPREMLJENI TERMINI':'ARHIVA AKCIJE'}</span><h2>${live?'Termini povezani sa statusima':action.state==='Planirano'?'Rezervacije čekaju početak prijema':'Istorija dolazaka i zatvoreni tok'}</h2><p>Zapisi su sintetički i odvojeni po akciji.</p></div><button class="table-button" data-action="open-shared-action-picker" data-target-screen="operations">${workIcon('calendar')} Promeni akciju</button></header><div class="checkin-list">${rows.map((row,index)=>`<button class="checkin-row" data-action="open-intake-record" data-reservation="${row[2]}"><span class="checkin-order">${String(index+1).padStart(2,'0')}</span><span class="staff-avatar">${row[1]}</span><span><strong>${row[0]}</strong><small>${row[2]} · termin ${row[3]}</small></span>${pill(row[4],statusTone(row[4]))}${workIcon('arrow')}</button>`).join('')||`<div class="empty-workspace"><span>${workIcon('calendar')}</span><h3>Nema zapisa za ovaj kontekst.</h3><p>Izaberite drugu akciju ili kreirajte raspored.</p></div>`}</div></section>`};
portalTemplates.medical=()=>{const action=currentAction(),live=action.state==='U toku',visits=actionRows(action,'medical');return `${renderWorkspaceHeader('MEDICINSKA SLUŽBA','Zaštićeni radni red po akciji',`<button class="primary-button compact" data-action="medical-audit">${workIcon('shield')} Pristupni audit</button>`)}<section class="medical-workspace-hero"><span>${workIcon('medical')}</span><div><span class="eyebrow">${action.name.toUpperCase()} · ${action.state.toUpperCase()}</span><h2>${live?'Aktivna smena: klinički red bez operativne buke.':action.state==='Planirano'?'Medicinska priprema je vezana za datum akcije.':'Arhiva je zatvorena i odvojena od aktivnog reda.'}</h2><p>Karton se otvara samo uz dodeljenu smenu, MFA i razlog pristupa. Planirane i završene akcije imaju zasebnu pripremu odnosno arhivu.</p></div><button class="table-button" data-action="open-shared-action-picker" data-target-screen="medical">${workIcon('calendar')} Izaberi akciju</button></section><section class="medical-command-grid">${[['Čeka pregled',live?visits.filter(x=>x.status==='Čeka pregled').length:'—','queue'],['U pregledu',live?visits.filter(x=>x.status==='U pregledu').length:'—','medical'],['Evidentiran ishod',visits.filter(x=>x.status==='Ishod evidentiran').length,'check'],['Audit pristupa','100%','shield']].map(item=>`<button class="premium-metric interactive-card" data-action="${item[0]==='Audit pristupa'?'medical-audit':'open-shared-action-picker'}" data-target-screen="medical"><span class="metric-visual">${workIcon(item[2])}</span><span><small>${item[0]}</small><strong>${item[1]}</strong><em>${live?'Aktivna smena':action.state}</em></span>${workIcon('arrow')}</button>`).join('')}</section><section class="workspace-columns"><section class="premium-panel"><header class="premium-panel-head"><div><span class="eyebrow">${live?'AKTIVNI RED':action.state==='Planirano'?'MEDICINSKA PRIPREMA':'ODOBRENA ARHIVA'}</span><h2>${action.name}</h2></div><button class="table-button" data-action="medical-audit">${workIcon('shield')} Audit</button></header><div class="medical-worklist premium-worklist">${visits.length?visits.map((visit,index)=>`<button class="medical-visit-card premium-visit ${visit.tone}" data-action="${visit.id&&visit.id.startsWith('archive-')?'open-demo-route':'open-medical-visit'}" ${visit.id&&visit.id.startsWith('archive-')?'data-route="medical-history"':`data-visit="${visit.id}"`}><span class="visit-order">${String(index+1).padStart(2,'0')}</span><span class="staff-avatar">${visit.initials}</span><span><strong>${visit.name}</strong><small>${visit.reference} · termin ${visit.time} · prijem ${visit.checkIn}</small><p>${visit.history}</p></span><span>${pill(visit.status,visit.tone)}${workIcon('arrow')}</span></button>`).join(''):`<div class="empty-workspace"><span>${workIcon(action.state==='Planirano'?'calendar':'report')}</span><h3>${action.state==='Planirano'?'Medicinski red se otvara sa početkom akcije.':'Nema pojedinačnih kartona u prikazu portala.'}</h3><p>${action.state==='Planirano'?'Priprema obuhvata tim, smenu i bezbedan pristup — bez podataka davaoca.':'Za završenu akciju ostaju odobreni zbirni podaci i audit pristupa.'}</p><button class="primary-button compact" data-portal-screen="reports">Otvori zbirni izveštaj</button></div>`}</div></section><aside class="workspace-side">${routeCard('shield','ZAŠTIĆEN TOK','Granica medicinskog pristupa','Razlog, vreme i korisnik ostaju u neizmenjivom auditu.','governance','Otvori audit')}${routeCard('calendar','AKCIJA','Promeni radni kontekst','Planirani i završeni tokovi ne mešaju se sa aktivnom smenom.','#choose-action','Izaberi akciju')}</aside></section>`};
/* R5 — uklanja automatsko dupliranje ikonica i popravlja kontrole rasporeda. */
decoratePortalActions=()=>{};
const calendarYears=Array.from({length:101},(_,index)=>2000+index);
function calendarGrid(){const date=monthMeta(),offset=(date.getDay()+6)%7,days=new Date(state.calendarYear,state.calendarMonth+1,0).getDate(),monthLabel=date.toLocaleDateString('sr-Latn-RS',{month:'long',year:'numeric'}),cells=[...Array(offset).fill(null),...Array.from({length:days},(_,index)=>index+1)];return `<section class="scheduler-shell"><header><div><span class="eyebrow">RASPORED AKCIJA</span><h2>${monthLabel[0].toUpperCase()+monthLabel.slice(1)}</h2><p>Izaberite mesec, godinu ili dan. Dostupne su prethodne, tekuće i buduće akcije.</p></div><div class="scheduler-controls"><button data-action="calendar-shift" data-step="-1" aria-label="Prethodni mesec">${workIcon('arrow')}</button><select data-action="calendar-month" aria-label="Izaberi mesec">${['januar','februar','mart','april','maj','jun','jul','avgust','septembar','oktobar','novembar','decembar'].map((name,index)=>`<option value="${index}" ${state.calendarMonth===index?'selected':''}>${name[0].toUpperCase()+name.slice(1)}</option>`).join('')}</select><select data-action="calendar-year" aria-label="Izaberi godinu">${calendarYears.map(year=>`<option value="${year}" ${state.calendarYear===year?'selected':''}>${year}</option>`).join('')}</select><button data-action="calendar-shift" data-step="1" aria-label="Sledeći mesec">${workIcon('arrow')}</button></div></header><div class="calendar-weekdays">${['PON','UTO','SRE','ČET','PET','SUB','NED'].map(day=>`<span>${day}</span>`).join('')}</div><div class="scheduler-days">${cells.map(day=>{if(!day)return '<span class="scheduler-empty"></span>';const key=`${state.calendarYear}-${String(state.calendarMonth+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,events=scheduledCalendarEvents.filter(item=>item.date===key),selected=state.selectedCalendarDate===key;return `<button class="scheduler-day ${events.length?'has-event':''} ${selected?'selected':''}" data-action="calendar-date" data-date="${key}"><strong>${day}</strong>${events.length?`<small>${events.length} akcija</small><i></i>`:'<small>—</small>'}</button>`}).join('')}</div></section>`}
function renderPortalStreetMap(containerId){const container=document.getElementById(containerId);if(!container||!window.L)return;if(portalStreetMap){portalStreetMap.remove();portalStreetMap=null}portalStreetMap=L.map(container,{zoomControl:false,scrollWheelZoom:true,attributionControl:true,minZoom:6,maxZoom:18}).setView([44.2,20.8],7);L.control.zoom({position:'bottomright'}).addTo(portalStreetMap);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(portalStreetMap);const bounds=[];portalMapLocations.forEach(location=>{const marker=L.circleMarker(location.coords,{radius:10,color:'#fff',weight:3,fillColor:location.tone,fillOpacity:1}).addTo(portalStreetMap);marker.bindPopup(`<div class="portal-map-popup"><strong>${location.name}</strong><span>${location.city} · ${location.type}</span><small>${location.detail}</small><button type="button" data-action="open-map-location" data-location="${location.name}">Pogledaj kompletnu akciju</button></div>`,{minWidth:230});marker.on('click',()=>marker.openPopup());bounds.push(location.coords)});portalStreetMap.fitBounds(bounds,{padding:[42,42]});setTimeout(()=>portalStreetMap?.invalidateSize(),0)}
document.addEventListener('click',event=>{if(event.target.closest('select[data-action="calendar-month"],select[data-action="calendar-year"]'))event.stopImmediatePropagation()},true);
document.addEventListener('click',event=>{const target=event.target.closest('[data-portal-screen]');if(!target)return;event.stopImmediatePropagation();if(dialog.open)dialog.close();setPortalMenu(false);renderPortal(target.dataset.portalScreen)},true);
document.addEventListener('click',event=>{const node=event.target.closest('[data-action="open-map-location"]');if(!node)return;const location=portalMapLocations.find(item=>item.name===node.dataset.location);if(!location)return;showDialog(`${location.name} · detalji akcije`,`<section class="dialog-map-intro"><span class="eyebrow">${location.city.toUpperCase()} · ${location.type.toUpperCase()}</span><h3>${location.name}</h3><p>${location.detail}. Lokacija je demonstraciona dok Zavod ne poveže odobreni operativni izvor.</p></section><div class="decision-grid"><article class="decision-card"><h3>Termin i kapacitet</h3><p>Planirani raspored, radno vreme, kapacitet i status prijema pripadaju izabranoj akciji.</p></article><article class="decision-card"><h3>Odgovorni tim</h3><p>Koordinator, prijem i medicinska služba vide samo svoj dodeljeni radni prostor.</p></article></div><div class="button-row" style="margin-top:14px"><button class="ghost-button" data-portal-screen="dashboard">Nazad na mapu</button><button class="primary-button" data-portal-screen="${location.screen}">Otvori radni prostor</button></div>`)});
document.addEventListener('click',event=>{const node=event.target.closest('[data-action="open-staff-member"]');if(node)state.selectedStaffId=node.dataset.staff||node.closest('[data-staff]')?.dataset.staff},true);
document.addEventListener('click',event=>{const node=event.target.closest('[data-action="edit-staff-assignment"]');if(!node)return;event.stopImmediatePropagation();const member=staffDirectory.find(item=>item.id===state.selectedStaffId)||staffDirectory[0];showDialog(`Promena ovlašćenja · ${member.name}`,`<div class="form-grid"><div class="field"><label>Pozicija</label><select><option>${member.position}</option><option>Administrator</option><option>Koordinator akcija</option><option>Osoblje na prijemu</option><option>Medicinska služba</option><option>PR i sadržaj</option><option>Revizor</option></select></div><div class="field"><label>Dodeljena akcija</label><select><option>${member.actions}</option><option>Dom omladine</option><option>Sve javne akcije</option><option>Nije vezan za akciju</option></select></div><div class="field"><label>Rok pristupa</label><input type="date" value="2026-12-31"></div><div class="field"><label>Status</label><select><option>Aktivan</option><option>Privremeno obustavljen</option><option>Opozvan</option></select></div><div class="field full"><label>Razlog izmene</label><textarea placeholder="Obavezan razlog za audit promene ovlašćenja."></textarea></div></div><div class="warning-box" style="margin-top:14px">U produkciji samo Super admin potvrđuje promenu uz MFA, razlog i neizmenjiv audit.</div><button class="primary-button compact" style="margin-top:14px" data-action="save-staff-assignment">Sačuvaj demonstracionu izmenu</button>`)} ,true);
document.addEventListener('click',event=>{if(event.target.closest('[data-action="save-staff-assignment"]')){dialog.close();showToast('Demonstraciona izmena ovlašćenja je evidentirana sa razlogom i audit tragom.')}},true);
document.addEventListener('click',event=>{const card=event.target.closest('.approval-summary .metric-card');if(!card)return;const label=card.querySelector('small')?.textContent||'Pregled odobravanja',value=card.querySelector('strong')?.textContent||'—';showDialog(label,`<div class="route-dialog"><span>${workIcon('check')}</span><h3>${label}: ${value}</h3><p>Sažetak je povezan sa radnim redom odobravanja. Otvorite stavku da biste videli vlasnika, rok i audit promene.</p><button class="primary-button" data-portal-screen="approvals">Otvori radni red</button></div>`)});
/* R6 — lokalno čuvanje redakcijskih nacrta u demonstracionom portalu. */
const newsDraftStorageKey='kapi-zivota.portal-news-drafts';
try{const savedNewsDrafts=JSON.parse(localStorage.getItem(newsDraftStorageKey)||'[]');if(Array.isArray(savedNewsDrafts))portalNews.unshift(...savedNewsDrafts.filter(item=>item&&item.id&&item.title))}catch{localStorage.removeItem(newsDraftStorageKey)}
function saveNewsDraftFromDialog(){const field=name=>dialog.querySelector(`[data-news-field="${name}"]`),title=field('title')?.value.trim(),type=field('type')?.value||'Vest',summary=field('summary')?.value.trim(),source=field('source')?.value.trim(),schedule=field('schedule')?.value;if(!title){showToast('Unesite naslov pre čuvanja nacrta.');return}const draft={id:`news-local-${Date.now()}`,type,status:'Nacrt',tone:'neutral',title,summary:summary||'Nacrt je sačuvan bez sažetka.',author:'Ana Ilić · PR',reviewer:source?`Izvor: ${source}`:'Čeka izvor i stručnu proveru',updated:'upravo sada',schedule:schedule||null};portalNews.unshift(draft);try{localStorage.setItem(newsDraftStorageKey,JSON.stringify(portalNews.filter(item=>item.id.startsWith('news-local-'))))}catch{}dialog.close();renderPortal('content');showToast('Nacrt je sačuvan i dodat u radnu tablu sadržaja.')}
document.addEventListener('click',event=>{const node=event.target.closest('[data-action="create-news"]');if(!node)return;event.stopImmediatePropagation();showDialog('Nova vest · nacrt',`<div class="form-grid"><div class="field"><label>Naslov</label><input data-news-field="title" placeholder="Jasan naslov za javnu objavu"></div><div class="field"><label>Vrsta sadržaja</label><select data-news-field="type"><option>Vest</option><option>Vodič</option><option>Akcija</option><option>Podrška posle davanja</option></select></div><div class="field"><label>Plan objave</label><input data-news-field="schedule" type="datetime-local"></div><div class="field"><label>Odgovorni urednik</label><input value="Ana Ilić · PR" readonly></div><div class="field full"><label>Sažetak</label><textarea data-news-field="summary" placeholder="Najvažnije informacije u nekoliko jasnih rečenica."></textarea></div><div class="field full"><label>Izvor i stručna provera</label><input data-news-field="source" placeholder="Obavezan izvor za medicinsku ili stručnu tvrdnju"></div></div><div class="warning-box" style="margin-top:14px">Nacrt nije javna objava. Sačuvani nacrt se odmah prikazuje u radnoj tabli i ostaje u ovom pregledaču.</div><button class="primary-button compact" style="margin-top:14px" data-action="save-news-draft">Sačuvaj nacrt</button>`)},true);
document.addEventListener('click',event=>{if(!event.target.closest('[data-action="save-news-draft"]'))return;if(!dialog.querySelector('[data-news-field="title"]'))return;event.stopImmediatePropagation();saveNewsDraftFromDialog()},true);
dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
renderMobileList();
const hash=location.hash.replace('#','').split('/');
if(hash[0]==='portal'||isAdminEntry){state.portalScreen=hash[1]||'dashboard';setMode('portal')}else{state.mobileScreen=hash[1]||'home';setMode('mobile')}
